-- Re-applies every migration in order (0001 -> latest). Run after the nuke script.
-- Generated by concatenating supabase/migrations/*.sql; regenerate when migrations change.

-- ===== 0001_events_organiser_scoping.sql =====
-- E1-3: Organiser data scoping
-- Minimal events schema plus RLS so organisers can only read their own events.
-- Columns beyond organiser_id/status/coordinator_id/review_outcome belong to
-- E1-2 (event creation) and should be extended there, not here.

create table if not exists events (
  id uuid primary key default gen_random_uuid(),
  organiser_id uuid not null references auth.users (id),
  status text not null default 'submitted',
  submitted_details jsonb not null default '{}'::jsonb,
  coordinator_id uuid references auth.users (id),
  review_outcome text,
  created_at timestamptz not null default now()
);

create table if not exists access_denials (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id),
  event_id uuid not null,
  reason text not null,
  attempted_at timestamptz not null default now()
);

alter table events enable row level security;
alter table access_denials enable row level security;

-- Organisers can only see events they created.
create policy "organisers_select_own_events"
  on events for select
  using (organiser_id = auth.uid());

-- Users can only read their own audit rows.
create policy "users_select_own_access_denials"
  on access_denials for select
  using (user_id = auth.uid());

-- Any authenticated user can insert a denial record about themselves
-- (the service inserts these on the user's behalf when access is denied).
create policy "users_insert_own_access_denials"
  on access_denials for insert
  with check (user_id = auth.uid());

-- ===== 0002_coordinator_scoping.sql =====
-- E1-4.1: Coordinator data scoping
-- Coordinators (role = 'coordinator' in app_metadata) can read all events.
-- The existing organisers_select_own_events policy is unaffected — organisers
-- still only see their own rows. These two policies are additive: Postgres
-- grants access if ANY matching policy passes.

create policy "coordinators_select_all_events"
  on events for select
  using (auth.jwt() -> 'app_metadata' ->> 'role' = 'coordinator');

-- ===== 0002_organiser_submit_event.sql =====
-- E2-1: Submit an event request
-- 0001 only granted organisers SELECT on events; submitting a request needs
-- an INSERT policy too. Additive only — 0001's schema/policies are untouched.

create policy "organisers_insert_own_events"
  on events for insert
  with check (organiser_id = auth.uid());

-- ===== 0003_access_denials_event_id_text.sql =====
-- Fix: malformed/garbage event IDs (e.g. /events/abc) were skipping the
-- audit log because event_id was typed uuid — a non-UUID string couldn't be
-- inserted, so the app-layer validation added alongside this migration
-- (isUuid) needs event_id to accept arbitrary attempted values, not just
-- valid UUIDs. No FK relies on this column, so widening it is safe.

alter table access_denials
  alter column event_id type text;

-- ===== 0004_user_roles.sql =====
-- Custom auth: public.users is now the sole source of truth for accounts
-- and credentials — Supabase Auth (auth.users/auth.identities) is no
-- longer used for login. The backend hashes passwords with bcrypt and
-- issues/verifies its own JWTs; RLS is not relied on for authorization
-- going forward (the backend uses the Supabase service-role key, which
-- bypasses RLS, and enforces ownership/role checks in application code
-- instead). Existing RLS policies from 0001/0002/0003 are dropped below
-- since they reference columns being repointed and can never match again
-- (auth.uid() only exists for Supabase Auth-issued JWTs).
--
-- Per requirements (epic E1, ConnectSphere PRD v1.0 section 2), there are
-- five roles and explicitly no admin role. New accounts default to
-- 'attendee' (E1-1).
--
-- Known limitation: a user's readable ID prefix reflects their role at
-- signup time. Since signup always defaults to 'attendee', a later
-- promotion to organiser/coordinator does not regenerate the ID.
-- Acceptable for now — there's no promotion flow defined yet.
--
-- Guards throughout make this migration safe to re-run after a partial
-- failure (e.g. a prior attempt that got interrupted mid-way).

do $$
begin
  if not exists (select 1 from pg_type where typname = 'app_role') then
    create type app_role as enum (
      'attendee',
      'organiser',
      'coordinator',
      'venue_staff',
      'technical_support',
      'coordinator_lead',
      'safety_officer'
    );
  end if;
end
$$;

create sequence if not exists organiser_id_seq;
create sequence if not exists coordinator_id_seq;
create sequence if not exists attendee_id_seq;
create sequence if not exists venue_staff_id_seq;
create sequence if not exists technical_support_id_seq;
create sequence if not exists coordinator_lead_id_seq;
create sequence if not exists safety_officer_id_seq;

create or replace function generate_user_id(p_role app_role)
returns text
language plpgsql
as $$
begin
  return case p_role
    when 'organiser' then 'ORG-' || lpad(nextval('organiser_id_seq')::text, 4, '0')
    when 'coordinator' then 'COORD-' || lpad(nextval('coordinator_id_seq')::text, 4, '0')
    when 'attendee' then 'ATT-' || lpad(nextval('attendee_id_seq')::text, 4, '0')
    when 'venue_staff' then 'VEN-' || lpad(nextval('venue_staff_id_seq')::text, 4, '0')
    when 'technical_support' then 'TS-' || lpad(nextval('technical_support_id_seq')::text, 4, '0')
    when 'coordinator_lead' then 'LEAD-' || lpad(nextval('coordinator_lead_id_seq')::text, 4, '0')
    when 'safety_officer' then 'SAF-' || lpad(nextval('safety_officer_id_seq')::text, 4, '0')
  end;
end;
$$;

create table if not exists users (
  id text primary key,
  name text not null,
  email text not null unique,
  password_hash text not null,
  role app_role not null default 'attendee',
  created_at timestamptz not null default now()
);

-- Enabled with no policies: deny-all by default for the anon/authenticated
-- Supabase keys. The backend accesses this table exclusively via the
-- service-role key, which bypasses RLS entirely, so this is a safety net
-- against any other key ever touching it directly.
alter table users enable row level security;

-- These policies reference organiser_id/coordinator_id/user_id and would
-- block the type changes below. They're dead weight anyway once the
-- backend uses the service-role key (bypasses RLS).
drop policy if exists "organisers_select_own_events" on events;
drop policy if exists "organisers_insert_own_events" on events;
drop policy if exists "users_select_own_access_denials" on access_denials;
drop policy if exists "users_insert_own_access_denials" on access_denials;

-- Old rows still hold auth.users uuids in these columns, which can never
-- match public.users.id (text). This is dev/seed data — clear it here so
-- the new FK constraints below can be added; seed.sql repopulates it.
truncate table access_denials;
truncate table events;

-- events.organiser_id/coordinator_id and access_denials.user_id were uuid
-- FKs into auth.users. Now that public.users (text id, e.g. ORG-0001) is
-- the identity source of truth, repoint them there.
alter table events drop constraint if exists events_organiser_id_fkey;
alter table events drop constraint if exists events_coordinator_id_fkey;
alter table events alter column organiser_id type text using organiser_id::text;
alter table events alter column coordinator_id type text using coordinator_id::text;
alter table events add constraint events_organiser_id_fkey
  foreign key (organiser_id) references users (id);
alter table events add constraint events_coordinator_id_fkey
  foreign key (coordinator_id) references users (id);

alter table access_denials drop constraint if exists access_denials_user_id_fkey;
alter table access_denials alter column user_id type text using user_id::text;
alter table access_denials add constraint access_denials_user_id_fkey
  foreign key (user_id) references users (id);

-- ===== 0005_events_integer_id.sql =====
-- Switch events.id from a uuid (gen_random_uuid()) to an auto-incrementing
-- integer. events was truncated in 0004 while repointing organiser_id/
-- coordinator_id, so there's no existing data to convert.
--
-- Guarded so this is safe to re-run if it partially applied before.

do $$
begin
  if (
    select data_type from information_schema.columns
    where table_name = 'events' and column_name = 'id'
  ) = 'uuid' then
    alter table events drop constraint if exists events_pkey;
    alter table events alter column id drop default;
    alter table events alter column id type integer using null;
    alter table events alter column id add generated by default as identity;
    alter table events add constraint events_pkey primary key (id);
  end if;
end
$$;

-- ===== 0006_login_lockout.sql =====
-- E1-2 secure login: account lockout after repeated failed logins.
--
-- Team-chosen policy (issue #9, PRD open question Q4): 5 consecutive
-- failed attempts lock the account for 15 minutes. The thresholds
-- themselves live in the backend (src/routes/auth.ts) so they can be
-- tuned without a migration; only the per-user state is stored here.
--
-- State lives in the DB rather than backend memory so a lockout survives
-- a process restart and holds across multiple backend instances.
--
-- Guarded so this is safe to re-run.

alter table users add column if not exists failed_login_attempts integer not null default 0;

-- Null means "not locked". A timestamp in the past means the lockout has
-- expired; the backend treats that as unlocked and resets the counter on
-- the next attempt, so no cleanup job is needed.
alter table users add column if not exists locked_until timestamptz;

-- ===== 0007_coordinator_review_decision.sql =====
-- E1-4.2: Coordinator approves/rejects/requests clarification on a request.
--
-- review_outcome (0001) already holds the free-text note ("Rejected —
-- venue unavailable after 10pm"), so it's reused here as the decision
-- reason/clarification message. decided_at/decided_by are new: created_at
-- is submission time, not decision time, and the Organiser needs to see
-- when (and by whom) a decision was made (AC4).
--
-- Status values this feature introduces, alongside the existing
-- "Requested" (E2-1): "Planning", "Rejected", "Clarification Requested".
-- Capitalized to match "Requested", the one other status value the app
-- itself writes — seed.sql's older lowercase 'approved'/'submitted'/
-- 'rejected' values have been migrated onto this scheme too.
--
-- Guarded so this is safe to re-run.

alter table events add column if not exists decided_at timestamptz;
alter table events add column if not exists decided_by text references users (id);

-- ===== 0008_event_clarifications.sql =====
-- E2-3: Coordinator asks the Organiser for clarification/amendment.
--
-- 0007's review_outcome/status only capture a single free-text message —
-- enough to flag "Clarification Requested" but not a back-and-forth. This
-- table holds the full thread the clarification popup renders: top-level
-- questions (parent_id null) and the replies threaded under each one
-- (parent_id = that question's id). Replies are one level deep — no
-- reply-to-a-reply — matching the "Qn 1 -> its replies" shape in the UI.
--
-- Guarded so this is safe to re-run.

create table if not exists event_clarifications (
  id bigserial primary key,
  event_id integer not null references events (id),
  parent_id bigint references event_clarifications (id),
  author_id text not null references users (id),
  author_role text not null check (author_role in ('coordinator', 'organiser')),
  message text not null,
  created_at timestamptz not null default now()
);

create index if not exists event_clarifications_event_id_idx on event_clarifications (event_id);
create index if not exists event_clarifications_parent_id_idx on event_clarifications (parent_id);

-- ===== 0009_event_clarifications_resolved.sql =====
-- E2-3: coordinator marks each clarification question resolved once the
-- Organiser's reply satisfies it. Approval (0007) stays blocked while any
-- top-level question (parent_id null) for the event has resolved = false;
-- once every question is resolved, the coordinator can approve without
-- the Organiser needing to resubmit.
--
-- Guarded so this is safe to re-run.

alter table event_clarifications add column if not exists resolved boolean not null default false;

-- ===== 0010_clarification_during_planning.sql =====
-- Lets a coordinator request clarification even after an event has moved
-- to "Planning" (post-approval), not just before approval. Since the
-- status returns to "Clarification Requested" either way, we need to
-- remember what to restore it to once the organiser responds — "Requested"
-- if it was requested pre-approval, "Planning" if it was already approved.
--
-- Guarded so this is safe to re-run.

alter table events add column if not exists status_before_clarification text;

-- ===== 0011_venues.sql =====
-- E4 venue search: Coordinator filters venues by date/time, attendance,
-- location, capacity, accessibility, layout and facilities to shortlist
-- realistic options.
--
-- venues holds the searchable attributes. accessibility/layouts/facilities
-- are text[] rather than join tables: the filter is "venue has ALL of the
-- selected values", which is a single array-containment check, and the
-- option lists are small and descriptive rather than entities in their own
-- right. Values are stored as the display label ("Wheelchair access") so
-- the filter options can be derived straight from the table without a
-- separate lookup.
--
-- venues.status is the venue's own availability (Available = searchable and
-- bookable), and is not to be confused with the booking-approval enum
-- `venue_booking_status` on venue_bookings (migration 0014).
--
-- venue_bookings is what makes a venue unavailable for a date/time window
-- (AC2). It stores no timing of its own: a booking's date and times always
-- come from its linked event (events.submitted_details, read through
-- events-service's GET /venue-booking-info), so there is nothing to keep in
-- sync. event_id is therefore mandatory — there is no "external hold"
-- booking without an event.
--
-- Periods a venue is unavailable (maintenance, equipment failure,
-- renovation, safety) live in venue_unavailability, created by migration
-- 0016 — not here.
--
-- Guarded so this is safe to re-run.

do $$
begin
  if not exists (select 1 from pg_type where typname = 'venue_availability_status') then
    create type venue_availability_status as enum ('Available', 'Unavailable');
  end if;
end
$$;

create table if not exists venues (
  id integer generated by default as identity primary key,
  name text not null,
  location text not null,
  description text,
  capacity integer not null check (capacity > 0),
  accessibility text[] not null default '{}',
  layouts text[] not null default '{}',
  facilities text[] not null default '{}',
  status venue_availability_status not null default 'Available',
  -- Still read by parts of the codebase that predate `status`; kept until
  -- they all move over.
  active boolean not null default true,
  -- Week 7 change 1: availability checks count these around each event.
  setup_minutes integer not null default 0 check (setup_minutes >= 0),
  turnaround_minutes integer not null default 0 check (turnaround_minutes >= 0),
  created_at timestamptz not null default now()
);

-- For databases created before these columns existed.
alter table venues add column if not exists status venue_availability_status not null default 'Available';
alter table venues add column if not exists active boolean not null default true;
alter table venues add column if not exists setup_minutes integer not null default 0;
alter table venues add column if not exists turnaround_minutes integer not null default 0;

-- `status` is the venue's own availability. The older `active` boolean is
-- deliberately left in place for now: part of the codebase still reads it,
-- so a venue taken out of use must be updated in both until everything
-- moves over to `status`.
update venues set status = 'Unavailable' where active = false;

-- Week 7 change 2 (venue unavailable after booking): the venue_unavailability
-- table is created in 0016_venue_unavailability.sql (E4-3). A period there
-- is a date range that either blocks whole days or the same hours on each
-- day, so "09:00–13:00 every day for a week" is one row.

create table if not exists venue_bookings (
  id bigserial primary key,
  venue_id integer not null references venues (id) on delete cascade,
  event_id integer not null references events (id) on delete cascade,
  created_at timestamptz not null default now()
);

-- For databases created while a booking duplicated its event's timing: drop
-- those columns and their date indexes, remove the event-less "external
-- hold" rows, and require a real event. on delete cascade replaces the old
-- on delete set null, since a booking can't survive its event being deleted
-- without violating not null.
drop index if exists venue_bookings_venue_date_idx;
drop index if exists venue_bookings_date_idx;

alter table venue_bookings drop column if exists booking_date;
alter table venue_bookings drop column if exists start_time;
alter table venue_bookings drop column if exists end_time;
alter table venue_bookings drop column if exists reason;

delete from venue_bookings where event_id is null;

alter table venue_bookings drop constraint if exists venue_bookings_event_id_fkey;
alter table venue_bookings alter column event_id set not null;
alter table venue_bookings add constraint venue_bookings_event_id_fkey
  foreign key (event_id) references events (id) on delete cascade;

create index if not exists venue_bookings_venue_id_idx on venue_bookings (venue_id);

-- Same stance as users (0004): RLS on with no policies, so only the
-- backend's service-role key can reach these tables.
alter table venues enable row level security;
alter table venue_bookings enable row level security;

-- ===== 0012_event_history.sql =====
-- E2-7 AC3: structured edit-history audit trail. One row per changed
-- field (not one row per edit action), so it's directly queryable/sortable
-- as "field, old value, new value, timestamp, author" per the AC's
-- literal wording — distinct from event_clarifications, which is a Q&A
-- thread, not a field-level audit log.
--
-- Guarded so this is safe to re-run.

create table if not exists event_history (
  id bigserial primary key,
  event_id integer not null references events (id),
  field text not null,
  old_value text,
  new_value text,
  changed_by text not null references users (id),
  changed_at timestamptz not null default now()
);

create index if not exists event_history_event_id_idx on event_history (event_id);

-- Week 7 change 6 (E3-12/13/14): every Operational Safety Check outcome the
-- Safety Officer records. A reason is required unless the outcome is
-- 'Approved'. The event's status change itself is driven by events.status.
create table if not exists event_safety_reviews (
  id bigserial primary key,
  event_id integer not null references events (id),
  officer_id text not null references users (id),
  outcome text not null check (outcome in ('Approved', 'Rejected', 'Changes Requested')),
  reason text,
  created_at timestamptz not null default now(),
  check (outcome = 'Approved' or (reason is not null and length(trim(reason)) > 0))
);

create index if not exists event_safety_reviews_event_id_idx on event_safety_reviews (event_id);

alter table event_safety_reviews enable row level security;

-- ===== 0013_sync_user_id_sequences.sql =====
-- E1-1 (issue #8): self-signup can now create organisers as well as
-- attendees, so generate_user_id() (migration 0004) draws from
-- organiser_id_seq at signup time.
--
-- seed.sql inserts accounts with hand-picked IDs (ORG-0001, COORD-0001,
-- ...) without touching the sequences, so on a seeded database the first
-- organiser to sign up would be handed ORG-0001 and collide with the
-- seed row. Attendee signups never hit this only because no attendees
-- are seeded.
--
-- sync_user_id_sequences() moves each role's sequence past the highest
-- ID already in use for that prefix. It only ever moves a sequence
-- forward, so it's safe to call at any time — seed.sql calls it after
-- inserting its accounts, and it's run once below to repair databases
-- that were seeded before this migration existed.
--
-- Guarded so this is safe to re-run.

create or replace function sync_user_id_sequences()
returns void
language plpgsql
as $$
declare
  r record;
  max_used bigint;
  current_value bigint;
  called boolean;
begin
  for r in
    select * from (values
      ('ORG-', 'organiser_id_seq'),
      ('COORD-', 'coordinator_id_seq'),
      ('ATT-', 'attendee_id_seq'),
      ('VEN-', 'venue_staff_id_seq'),
      ('TS-', 'technical_support_id_seq'),
      ('LEAD-', 'coordinator_lead_id_seq'),
      ('SAF-', 'safety_officer_id_seq')
    ) as t(prefix, seq)
  loop
    select max(substring(id from length(r.prefix) + 1)::bigint)
      into max_used
      from users
      where id like r.prefix || '%'
        and substring(id from length(r.prefix) + 1) ~ '^[0-9]+$';

    continue when max_used is null;

    execute format('select last_value, is_called from %I', r.seq)
      into current_value, called;

    -- A never-used sequence reports last_value = start (1) with
    -- is_called = false, meaning nothing has been handed out yet.
    if not called then
      current_value := current_value - 1;
    end if;

    if max_used > current_value then
      perform setval(r.seq::regclass, max_used, true);
    end if;
  end loop;
end;
$$;

select sync_user_id_sequences();

-- ===== 0014_status_enums.sql =====
-- Converts events.status and venue_bookings' booking-approval status from
-- free text to Postgres enums. This captures in version control a change
-- that was made live in Supabase Studio — per AGENTS.md's migration rule
-- ("schema changes go in a new migration"), so a fresh environment ends
-- up with the same schema the dev project already has.
--
-- event_status: every status in AGENTS.md §3, including "Unassigned"
-- (the Event Coordinator Lead's unassigned queue) and "Safety Review"
-- (awaiting the Safety Officer's Operational Safety Check, Week 7 change 6)
-- and "Cancelled" (the Organiser cancelled their own event).
--
-- venue_booking_status: new, backs a booking-approval workflow (a booking request
-- for a venue gets approved/rejected — not the venue itself). The column
-- was created live as venue_bookings."Status" (capitalized); this
-- migration renames it to the lowercase `status` every other column in
-- the schema uses. Statuses and their meaning: AGENTS.md §3a (Week 7
-- changes 2 and 4 add "On Hold", "Expired" and "Replacement Required";
-- "Withdrawn" is a booking the coordinator released or that an event
-- cancellation released).
-- An "On Hold" booking is Venue Staff's tentative hold and carries
-- hold_expires_at, added below.
--
-- Guarded so this is safe to re-run.

do $$
begin
  if not exists (select 1 from pg_type where typname = 'event_status') then
    create type event_status as enum (
      'Draft',
      'Requested',
      'Unassigned',
      'Clarification Requested',
      'Planning',
      'Safety Review',
      'Rejected',
      'Confirmed',
      'Completed',
      'Cancelled'
    );
  end if;
end
$$;

alter table events alter column status drop default;
alter table events alter column status type event_status using status::text::event_status;
alter table events alter column status set default 'Requested'::event_status;

do $$
begin
  if not exists (select 1 from pg_type where typname = 'venue_booking_status') then
    create type venue_booking_status as enum (
      'Requested',
      'On Hold',
      'Approved',
      'Rejected',
      'Expired',
      'Replacement Required',
      'Withdrawn'
    );
  end if;
end
$$;

-- The dev project's enum was created by hand without 'On Hold' (Week 7
-- change 4 arrived later), and every availability check filters on it, so
-- add it to an existing type rather than assuming the list above.
alter type venue_booking_status add value if not exists 'On Hold' before 'Approved';

do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_name = 'venue_bookings' and column_name = 'Status'
  ) then
    alter table venue_bookings rename column "Status" to status;
  elsif not exists (
    select 1 from information_schema.columns
    where table_name = 'venue_bookings' and column_name = 'status'
  ) then
    alter table venue_bookings add column status venue_booking_status not null default 'Requested';
  end if;
end
$$;

alter table venue_bookings alter column status set default 'Requested'::venue_booking_status;

do $$
begin
  if not exists (select 1 from venue_bookings where status is null) then
    alter table venue_bookings alter column status set not null;
  end if;
end
$$;

-- Tentative-hold expiry (Week 7 change 4): an 'On Hold' booking blocks its
-- venue only until this moment. Null for every other status.
alter table venue_bookings add column if not exists hold_expires_at timestamptz;

-- ===== 0015_venue_booking_decisions.sql =====
-- E4-10: Venue Staff place a booking request on hold, approve it, or
-- reject it with a reason.
--
-- Rejecting requires a reason (E4-10 AC4) and the coordinator sees it on
-- the event's venue requests panel, so the decision is recorded on the
-- booking itself rather than in a separate log. decided_by is null when
-- the system made the decision: a booking auto-rejected because another
-- one reached "On Hold"/"Approved" first (§3a, E4-11), or a hold that
-- lapsed into "Expired" (E4-12).
--
-- venues.staff_id is who looks after that venue (E4-10 AC7: "I am not
-- Venue Staff for that venue" must block the action). Before this, the
-- venue_staff role granted every venue. A column rather than a join table,
-- so a venue has at most one assigned staff member; a venue with no
-- staff_id has nobody who can decide on its bookings. There is deliberately
-- no UI for maintaining it yet — it is set in Supabase Studio until an
-- admin flow exists — so the seed below gives every venue to the
-- longest-standing member of venue staff rather than leaving the queue
-- empty for everyone.
--
-- Guarded so this is safe to re-run.

alter table venue_bookings add column if not exists decision_reason text;
alter table venue_bookings add column if not exists decided_by text references users (id);
alter table venue_bookings add column if not exists decided_at timestamptz;

-- A rejection without a reason is the one state AC4 forbids. Backfill any
-- row that predates the column before the constraint goes on.
update venue_bookings
set decision_reason = 'Reason not recorded'
where status = 'Rejected' and (decision_reason is null or btrim(decision_reason) = '');

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'venue_bookings_rejection_reason_check'
  ) then
    alter table venue_bookings add constraint venue_bookings_rejection_reason_check
      check (status <> 'Rejected' or btrim(coalesce(decision_reason, '')) <> '');
  end if;
end
$$;

-- The pending queue (AC6) filters by status across every assigned venue.
create index if not exists venue_bookings_status_idx on venue_bookings (status);

alter table venues add column if not exists staff_id text references users (id);

create index if not exists venues_staff_idx on venues (staff_id);

-- Seed: every unassigned venue goes to the first venue_staff account, so
-- the decision queue works out of the box. Reassign per venue afterwards.
update venues
set staff_id = (select id from users where role = 'venue_staff' order by id limit 1)
where staff_id is null;

-- ===== 0016_venue_unavailability.sql =====
-- E4-3: venue staff block out periods when a venue can't be used, so
-- coordinators don't request slots that can't be honoured.
--
-- A period spans start_date..end_date (inclusive, local dates — the same
-- shape events store proposedDate in). It either blocks each of those days
-- entirely (all_day) or the same start_time..end_time window on each day
-- (e.g. 09:00–13:00 every morning of a maintenance week). The reason is
-- required: it's what staff and coordinators see on the calendar.
--
-- Owned by venue-service, alongside venues and venue_bookings.
--
-- 'Replacement Required' is part of venue_booking_status (0014); the add below only
-- catches up a dev database whose enum predates that. An Approved booking
-- that falls inside a new period is moved there, and its coordinator is
-- told an alternative venue is needed. The event itself is left untouched —
-- its status and details are preserved as they were (AGENTS.md §3a).
--
-- Guarded so this is safe to re-run.

create table if not exists venue_unavailability (
  id bigserial primary key,
  venue_id integer not null references venues (id) on delete cascade,
  start_date date not null,
  end_date date not null,
  all_day boolean not null default true,
  start_time time,
  end_time time,
  reason text not null check (length(btrim(reason)) > 0),
  created_by text,
  created_at timestamptz not null default now(),
  constraint venue_unavailability_date_order check (end_date >= start_date),
  constraint venue_unavailability_time_window check (
    (all_day and start_time is null and end_time is null)
    or (not all_day and start_time is not null and end_time is not null and end_time > start_time)
  )
);

create index if not exists venue_unavailability_venue_dates_idx
  on venue_unavailability (venue_id, start_date, end_date);

-- Same stance as venues/venue_bookings (0011): RLS on with no policies, so
-- only the backend's service-role key can reach the table.
alter table venue_unavailability enable row level security;

alter type venue_booking_status add value if not exists 'Replacement Required';

-- ===== 0017_notifications.sql =====
-- E7-1 (first slice): in-app notifications, owned by notification-service.
-- Other services create notifications through its REST API; they never
-- write this table directly. The first trigger is E4-3: a coordinator is
-- told when a venue they had an Approved booking at is blocked out.
--
-- recipient_id is a users.id (text, e.g. "COORD-0001"). It deliberately
-- has no foreign key: users belong to user-service, and this service only
-- stores the id it was handed.
--
-- read_at is null until the recipient opens their notification list.
--
-- Guarded so this is safe to re-run.

create table if not exists notifications (
  id bigserial primary key,
  recipient_id text not null,
  type text not null,
  title text not null,
  body text not null,
  link text,
  read_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists notifications_recipient_created_idx
  on notifications (recipient_id, created_at desc);

-- RLS on with no policies: only the backend's service-role key reaches it.
alter table notifications enable row level security;

-- ===== 0018_venue_setup_turnaround.sql =====
-- venues.setup_minutes / venues.turnaround_minutes. A fresh database already
-- gets them from 0011 (edited in place for Week 7 change 1); this catches up
-- a dev database created before that edit, where they were added by hand.
--
-- A booking occupies its venue from event start − setup to event end +
-- turnaround: a 10:00–12:00 event with 30 min setup and 45 min turnaround
-- ties the venue up 09:30–12:45. E4-3 block-outs are checked against that
-- occupied window, both when flagging affected bookings and when excluding
-- blocked venues from search.
--
-- Guarded so this is safe to re-run (and a no-op where the columns exist).

alter table venues add column if not exists setup_minutes integer not null default 0;
alter table venues add column if not exists turnaround_minutes integer not null default 0;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'venues_setup_minutes_check') then
    alter table venues add constraint venues_setup_minutes_check check (setup_minutes >= 0);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'venues_turnaround_minutes_check') then
    alter table venues add constraint venues_turnaround_minutes_check check (turnaround_minutes >= 0);
  end if;
end $$;

-- ===== 0019_venue_operating_hours.sql =====
-- E4 venue availability calendar: each venue's daily operating hours.
--
-- A coordinator's calendar shows time outside opening_time..closing_time
-- as unavailable, and only offers free slots inside it. The same hours
-- apply every day; per-weekday hours can be split out later if a venue
-- needs them. closing_time may be '24:00' for a venue open until midnight
-- (Postgres `time` accepts 24:00:00).
--
-- Defaults to 08:00–22:00 so existing venues get sensible hours without a
-- backfill; Venue Staff can change them per venue.
--
-- Owned by venue-service, alongside venues (0011).
--
-- Guarded so this is safe to re-run.

alter table venues add column if not exists opening_time time not null default '08:00';
alter table venues add column if not exists closing_time time not null default '22:00';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'venues_operating_hours_check') then
    alter table venues add constraint venues_operating_hours_check check (closing_time > opening_time);
  end if;
end $$;

-- ===== 0020_equipment_requests.sql =====
-- E5-1: Record equipment requirements. New entity (per AGENTS.md §1,
-- "equipment" is the example given) owned by a new equipment-service.
--
-- equipment_requests is the Event Coordinator's request, one row per
-- submission for an event (an event may accumulate more than one, same as
-- venue_bookings allows several venues per event). status stays 'Requested'
-- until Technical Support update it (E5-3, #50) — "Requested", "Arranged"
-- or "Partially Fulfilled" — kept as plain text rather than a Postgres enum
-- since the API already validates it. fulfillment_note is E5-3 AC2's note
-- on what remains outstanding when only partly fulfilled.
--
-- equipment_request_items is the list of items per request — equipment
-- type and quantity, per AC1. quantity > 0 is enforced here too (AC3), not
-- just in the API, since the backend uses the service-role key and nothing
-- else stands between a bad row and the table. (The Coordinator's form no
-- longer collects technical requirements; a database that still carries
-- that column from before has a harmless, unused one — nothing reads it.)
--
-- Guarded so this is safe to re-run.

create table if not exists equipment_requests (
  id bigint generated by default as identity primary key,
  event_id integer not null references events (id) on delete cascade,
  coordinator_id text not null references users (id),
  status text not null default 'Requested',
  fulfillment_note text,
  created_at timestamptz not null default now()
);

create table if not exists equipment_request_items (
  id bigint generated by default as identity primary key,
  request_id bigint not null references equipment_requests (id) on delete cascade,
  equipment_type text not null,
  quantity integer not null check (quantity > 0),
  created_at timestamptz not null default now()
);

create index if not exists equipment_requests_event_idx on equipment_requests (event_id);
create index if not exists equipment_request_items_request_idx on equipment_request_items (request_id);

-- Same stance as every other table since migration 0004: RLS on with no
-- policies, so only the backend's service-role key can reach these.
alter table equipment_requests enable row level security;
alter table equipment_request_items enable row level security;

-- ===== 0021_equipment_inventory.sql =====
-- Captures equipment/equipment_booking, which already exist in the live
-- dev database (made directly in Supabase Studio, same situation
-- migration 0014 documented for venue_bookings."Status") but were never
-- recorded in a migration file. Guarded so this is safe to re-run both
-- here and against the database that already has them.
--
-- These are early scaffolding for a future story (equipment availability
-- /reservation — E5-4/E5-6), separate from E5-1's equipment_requests
-- (migration 0020): a request is what a coordinator asks for, this is the
-- inventory it would eventually be checked and reserved against. Neither
-- table is read or written by any backend code yet.
--
-- Known rough edge, kept as-is here rather than silently "fixed" in a
-- migration meant to just capture current state — worth a look before
-- E5-4/E5-6 build on this:
--   - Neither table has a quantity column, so representing "40 folding
--     tables" needs 40 rows, one per physical unit.
--
-- equipment.status originally reused the *event* status enum (Planning,
-- Safety Review, Cancelled, ...), which said nothing about whether a piece
-- of equipment is usable — fixed in place here (E5-4, migration 0025) with
-- a real equipment_status enum, rather than left for a later migration to
-- correct on every fresh install.

do $$
begin
  if not exists (select 1 from pg_type where typname = 'equipment_status') then
    create type equipment_status as enum ('Available', 'Damaged', 'Under Maintenance');
  end if;
end
$$;

create table if not exists equipment (
  id bigint generated by default as identity primary key,
  type text not null,
  status equipment_status not null default 'Available'
);

create table if not exists equipment_booking (
  id bigint generated by default as identity primary key,
  equipment_id bigint references equipment (id),
  event_id integer references events (id),
  created_at timestamptz not null default now()
);

create index if not exists equipment_booking_equipment_idx on equipment_booking (equipment_id);
create index if not exists equipment_booking_event_idx on equipment_booking (event_id);

-- Same stance as every other table since migration 0004: RLS on with no
-- policies, so only the backend's service-role key can reach these.
alter table equipment enable row level security;
alter table equipment_booking enable row level security;

-- ===== 0022_equipment_catalog.sql =====
-- E5-1/E5-3 stock tracking: Technical Support need to see how much of each
-- equipment type is actually available, not just the free-text requests
-- coming in. equipment_catalog is the fixed list Coordinators now pick
-- from (replacing the old free-text equipment_type input) and the stock
-- counter Technical Support's view shows alongside incoming requests.
--
-- available_stock only moves when Technical Support act on a request
-- (Requested itself reserves nothing): marking a request "Arranged" takes
-- the full requested quantity off the shelf, "Partially Fulfilled" takes
-- only what was actually handed out (recorded per item below), and moving
-- a request back to an earlier status returns whatever was taken. See
-- apply_equipment_request_status() below for the single place this math
-- happens.
--
-- Guarded so this is safe to re-run.

create table if not exists equipment_catalog (
  id bigint generated by default as identity primary key,
  name text not null unique,
  total_stock integer not null default 0 check (total_stock >= 0),
  available_stock integer not null default 0 check (available_stock >= 0 and available_stock <= total_stock),
  created_at timestamptz not null default now()
);

alter table equipment_catalog enable row level security;

-- Per-item link to the catalog (for stock math) and how much of that item
-- is currently taken off the shelf under the request's current status.
-- Nullable: rows recorded before this migration have no catalog entry and
-- simply never participate in stock tracking.
alter table equipment_request_items add column if not exists equipment_catalog_id bigint references equipment_catalog (id);
alter table equipment_request_items add column if not exists quantity_fulfilled integer not null default 0 check (quantity_fulfilled >= 0);

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'equipment_request_items_fulfilled_le_quantity'
  ) then
    alter table equipment_request_items
      add constraint equipment_request_items_fulfilled_le_quantity check (quantity_fulfilled <= quantity);
  end if;
end
$$;

create index if not exists equipment_request_items_catalog_idx on equipment_request_items (equipment_catalog_id);

-- Single place a request's status (and the stock it holds) changes.
-- Recomputes each item's quantity_fulfilled for the target status and
-- applies only the delta to equipment_catalog.available_stock, so moving
-- back and forth between statuses (e.g. Arranged -> Partially Fulfilled ->
-- Requested) always nets out correctly. p_fulfillments is only consulted
-- for 'Partially Fulfilled': a jsonb array of {"itemId": ..., "fulfilledQuantity": ...}.
-- Runs in the caller's transaction (PostgREST wraps each request in one),
-- so any raised exception rolls the whole update back — a request never
-- ends up with a status that doesn't match what was actually taken off
-- the shelf.
create or replace function apply_equipment_request_status(
  p_request_id bigint,
  p_status text,
  p_note text,
  p_fulfillments jsonb default '[]'::jsonb
)
returns void
language plpgsql
as $$
declare
  item record;
  target_fulfilled integer;
  delta integer;
  available integer;
begin
  if p_status not in ('Requested', 'Arranged', 'Partially Fulfilled') then
    raise exception 'Invalid status: %', p_status;
  end if;

  if not exists (select 1 from equipment_requests where id = p_request_id for update) then
    raise exception 'Equipment request not found: %', p_request_id;
  end if;

  for item in
    select id, quantity, quantity_fulfilled, equipment_catalog_id
    from equipment_request_items
    where request_id = p_request_id
    order by equipment_catalog_id, id
  loop
    if p_status = 'Requested' then
      target_fulfilled := 0;
    elsif p_status = 'Arranged' then
      target_fulfilled := item.quantity;
    else
      select (elem->>'fulfilledQuantity')::integer into target_fulfilled
      from jsonb_array_elements(p_fulfillments) elem
      where (elem->>'itemId')::bigint = item.id;

      if target_fulfilled is null then
        raise exception 'Missing fulfilled quantity for item %', item.id;
      end if;
      if target_fulfilled < 0 or target_fulfilled > item.quantity then
        raise exception 'Fulfilled quantity for item % must be between 0 and %', item.id, item.quantity;
      end if;
    end if;

    delta := target_fulfilled - coalesce(item.quantity_fulfilled, 0);

    if delta <> 0 and item.equipment_catalog_id is not null then
      select available_stock into available
        from equipment_catalog where id = item.equipment_catalog_id
        for update;

      if delta > 0 and available < delta then
        raise exception 'Not enough stock available for item %', item.id;
      end if;

      update equipment_catalog
        set available_stock = available_stock - delta
        where id = item.equipment_catalog_id;
    end if;

    update equipment_request_items
      set quantity_fulfilled = target_fulfilled
      where id = item.id;
  end loop;

  update equipment_requests
    set status = p_status, fulfillment_note = p_note
    where id = p_request_id;
end;
$$;

-- ===== 0022_venue_booking_locks.sql =====
-- E4-11 AC5: a real, cross-process mutex for one venue's hold/approve
-- decisions. lib/venueLock.ts only serialises decisions within a single
-- service instance (an in-memory queue); this table is the guard that
-- holds across several instances, closing the gap the project previously
-- covered only with a post-write re-check and rollback.
--
-- A row's existence *is* the lock: the primary key on venue_id means two
-- concurrent inserts for the same venue cannot both succeed — Postgres
-- itself picks the winner. locked_at lets a lock abandoned by a crashed
-- process be reclaimed instead of stuck forever. See
-- lib/venueBookingLock.ts for the acquire/release logic.

create table if not exists venue_booking_locks (
  venue_id integer primary key references venues (id),
  locked_at timestamptz not null default now()
);

-- ===== 0023_registrations.sql =====
-- E6: Attendee registration for an event. New entity, owned by the new
-- registration-service (AGENTS.md §1). One row per attendee per event.
--
-- status is the Postgres enum registration_status: 'Registered' while the
-- attendee holds a place, 'Withdrawn' once they give it up. The row stays
-- for history rather than being deleted, so re-registering later means
-- setting the same row back to 'Registered' (the unique constraint allows
-- only one row per attendee per event).
-- additional_info is optional free-form JSON (e.g. answers to a
-- registration form); null when the attendee supplied nothing.
--
-- Guarded so this is safe to re-run.

do $$
begin
  if not exists (select 1 from pg_type where typname = 'registration_status') then
    create type registration_status as enum ('Registered', 'Withdrawn');
  end if;
end
$$;

create table if not exists registrations (
  registration_id bigint generated by default as identity primary key,
  event_id integer not null references events (id) on delete cascade,
  user_id text not null references users (id) on delete cascade,
  status registration_status not null default 'Registered',
  created_at timestamptz not null default now(),
  additional_info jsonb,
  constraint registrations_event_user_unique unique (event_id, user_id)
);

create index if not exists registrations_user_idx on registrations (user_id);

-- Same stance as every other table since migration 0004: RLS on with no
-- policies, so only the backend's service-role key can reach this.
alter table registrations enable row level security;

-- ===== 0024_chat_messages.sql =====
-- E2-15: a live chat between an Organiser and their event's assigned
-- coordinator, owned by a new chat-service (AGENTS.md §1: a new domain
-- entity gets a new microservice — this is distinct from
-- event_clarifications, which is a status-gated, coordinator-initiated
-- Q&A thread baked into the review lifecycle, not a free-flowing chat).
--
-- One thread per event: event_id is the thread, so there is no separate
-- chat_threads table. Both parties for a thread are already on the event
-- row (organiser_id, coordinator_id) and read live through events-service,
-- never duplicated here.
--
-- read_at works the same way notifications.read_at does: a message has
-- exactly one recipient (the other party on a 1:1 thread), so a single
-- column is enough to track whether they've opened the thread since it
-- arrived — no separate per-recipient table needed.
--
-- A message requires a coordinator to already be assigned (chat-service
-- enforces this, not a constraint here, since it also needs to apply the
-- "event reached a terminal status" send-block, which isn't expressible as
-- a static check against this table alone).
--
-- Guarded so this is safe to re-run.

create table if not exists chat_messages (
  id bigint generated by default as identity primary key,
  event_id integer not null references events (id) on delete cascade,
  sender_id text not null references users (id),
  sender_role text not null check (sender_role in ('organiser', 'coordinator')),
  body text not null check (length(btrim(body)) > 0),
  read_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists chat_messages_event_created_idx on chat_messages (event_id, created_at);

-- Same stance as every other table since migration 0004: RLS on with no
-- policies, so only the backend's service-role key can reach it.
alter table chat_messages enable row level security;

-- ===== 0025_equipment_availability.sql =====
-- E5-4: Technical Support check whether enough suitable equipment is free
-- for an event's date/time before committing to it.
--
-- Fixes the rough edge migration 0021 flagged when it captured
-- `equipment`/`equipment_booking` as unused scaffolding: `equipment.status`
-- borrowed the *event* status enum (Planning, Safety Review, Cancelled,
-- ...), which says nothing about whether a piece of equipment is usable.
-- 0021 is edited in place (pre-prod) to create the real equipment_status
-- enum and use it from the start on a fresh database; this migration
-- catches up a dev database created before that edit, same as it already
-- had the old event_status-typed column.
--
-- Still no quantity column on `equipment`, by design: it stays one row per
-- physical unit (seed.sql mirrors equipment_catalog's totals this way), so
-- "available count" for a type is a row count, not a number pulled out of
-- a separate aggregate.
--
-- equipment_booking still has no status column — every row is a committed
-- reservation. That's within scope today because E5-4 only reads the
-- table; E5-6 (actually reserving equipment) is a separate story and can
-- extend this if it needs a pending/approved distinction later.
--
-- Transit time between venues is explicitly not modelled (customer
-- confirmed "none", per the issue) — unlike venue_bookings, there is no
-- setup/turnaround padding around an equipment booking's window.
--
-- Guarded so this is safe to re-run.

do $$
begin
  if not exists (select 1 from pg_type where typname = 'equipment_status') then
    create type equipment_status as enum ('Available', 'Damaged', 'Under Maintenance');
  end if;
end
$$;

-- Widen first so any existing value (including a leftover event_status
-- string, or null) survives the swap regardless of whether it's a valid
-- equipment_status — this table has no production data, but the guard
-- costs nothing and matches how 0014 handled the same kind of enum swap.
alter table equipment alter column status type text using status::text;
update equipment set status = 'Available' where status is null or status not in ('Available', 'Damaged', 'Under Maintenance');
alter table equipment alter column status type equipment_status using status::equipment_status;
alter table equipment alter column status set default 'Available'::equipment_status;
alter table equipment alter column status set not null;

create index if not exists equipment_type_status_idx on equipment (type, status);

-- ===== 0026_event_safety_submissions.sql =====
-- E3-4: the assigned coordinator submits an event for the Safety Officer's
-- Operational Safety Check (Week 7 change 6). Owned by events-service.
--
-- One row per submission, so a resubmission after the Safety Officer
-- rejects or requests changes gets fresh notes and the earlier decision
-- doesn't carry over (E3-12 AC4). The four notes are the ones E3-4 AC5
-- lists; each is required, so "blocked if empty" holds per field. Where
-- there are no restrictions, the coordinator writes "None known".
--
-- E1-10 shows the latest submission; E3-12/13/14 link their decision in
-- event_safety_reviews to the submission it answers via submission_id.
--
-- Guarded so this is safe to re-run.

create table if not exists event_safety_submissions (
  id bigserial primary key,
  event_id integer not null references events (id),
  submitted_by text not null references users (id),
  equipment_placement text not null check (length(trim(equipment_placement)) > 0),
  crowd_movement      text not null check (length(trim(crowd_movement)) > 0),
  emergency_access    text not null check (length(trim(emergency_access)) > 0),
  venue_restrictions  text not null check (length(trim(venue_restrictions)) > 0),
  submitted_at timestamptz not null default now()
);

create index if not exists event_safety_submissions_event_id_idx on event_safety_submissions (event_id);

alter table event_safety_submissions enable row level security;

alter table event_safety_reviews
  add column if not exists submission_id bigint references event_safety_submissions (id);

-- The status change and the notes land together or not at all. The update
-- only matches while the event is still in Planning and still assigned to
-- the submitter, so a concurrent submission, cancellation or reassignment
-- between events-service's checks and this call makes it return null
-- instead of moving the event. Returns the new submission's id.
create or replace function submit_event_for_safety_review(
  p_event_id integer,
  p_submitted_by text,
  p_equipment_placement text,
  p_crowd_movement text,
  p_emergency_access text,
  p_venue_restrictions text
) returns bigint
language plpgsql
as $$
declare
  v_submission_id bigint;
begin
  update events
     set status = 'Safety Review'
   where id = p_event_id
     and status = 'Planning'
     and coordinator_id = p_submitted_by;
  if not found then
    return null;
  end if;

  insert into event_safety_submissions (
    event_id, submitted_by, equipment_placement, crowd_movement, emergency_access, venue_restrictions
  ) values (
    p_event_id, p_submitted_by, p_equipment_placement, p_crowd_movement, p_emergency_access, p_venue_restrictions
  )
  returning id into v_submission_id;

  return v_submission_id;
end;
$$;

-- ===== 0027_equipment_reservations.sql =====
-- E5-6: Technical Support actually reserve equipment for an event, so it's
-- guaranteed and not double-allocated (AC1), rejected with the available
-- count shown when demand exceeds supply (AC2), re-checked and flagged when
-- the event's schedule changes (AC3), and released when the event is
-- cancelled (AC4).
--
-- Per the issue's own open question (PRD section 11): equipment is
-- requested for the event as a whole, not per venue (Change #3 only
-- confirmed an event can use several venues; nothing in the data model
-- ties an equipment request to one of them, and no AC asks for that
-- granularity) — so no venue_id is added here.
--
-- "Reserve" is folded into the existing E5-3 status workflow rather than a
-- new standalone action: marking an item Arranged or Partially Fulfilled is
-- already the real commitment point (it's what moves equipment_catalog's
-- counter), so that's also the moment specific physical units are claimed
-- via equipment_booking (migration 0025) for the event's date/time window —
-- making that claim date-aware, unlike the flat catalog counter. See
-- equipment-service's routes/equipmentRequests.ts PATCH handler and
-- lib/equipmentConflicts.ts for the per-unit claim/release logic (it has to
-- live in the application layer, not SQL, since it needs each other
-- booking's event schedule from events-service over HTTP).
--
-- Guarded so this is safe to re-run.

-- Which request item a claimed unit belongs to, so a reservation can be
-- released (or partially released, on a smaller re-fulfilment) one item at
-- a time. Nullable: the two pre-existing seeded rows (seed.sql) predate
-- this column and aren't tied to any request item.
alter table equipment_booking add column if not exists request_item_id bigint references equipment_request_items (id) on delete cascade;

create index if not exists equipment_booking_request_item_idx on equipment_booking (request_item_id);

-- AC4: cancelling an event (E3-6, #31 — not built yet) releases every
-- equipment reservation for it and returns the stock it held. Not called by
-- anything yet (there is no cancel-event endpoint in events-service to call
-- it), but ready for events-service to call the same way it already
-- forwards the caller's token to this service elsewhere (lib/eventsClient.ts,
-- lib/arrangementsClient.ts) once E3-6 ships. Exposed as
-- POST /api/equipment-requests/events/:eventId/release.
--
-- Mirrors apply_equipment_request_status (migration 0022): restores
-- available_stock by whatever each item currently holds, then zeroes
-- quantity_fulfilled — the request's own status (Requested/Arranged/
-- Partially Fulfilled) is left alone as history, same as a cancelled
-- event's record stays viewable. Runs in the caller's transaction
-- (PostgREST wraps each request in one).
create or replace function release_equipment_for_event(p_event_id integer)
returns void
language plpgsql
as $$
declare
  item record;
begin
  for item in
    select eri.id, eri.quantity_fulfilled, eri.equipment_catalog_id
    from equipment_request_items eri
    join equipment_requests er on er.id = eri.request_id
    where er.event_id = p_event_id and eri.quantity_fulfilled > 0
    order by eri.equipment_catalog_id, eri.id
  loop
    if item.equipment_catalog_id is not null then
      update equipment_catalog
        set available_stock = available_stock + item.quantity_fulfilled
        where id = item.equipment_catalog_id;
    end if;

    update equipment_request_items
      set quantity_fulfilled = 0
      where id = item.id;
  end loop;

  delete from equipment_booking where event_id = p_event_id;
end;
$$;

-- ===== 0028_safety_review_approve.sql =====
-- E3-12: the Safety Officer approves an event's Operational Safety Check
-- (Safety Review -> Confirmed). Owned by events-service.
--
-- Guarded so this is safe to re-run.

-- The status change and the decision land together or not at all. The
-- update only matches while the event is still in Safety Review, so a
-- concurrent decision or re-review (arrangements changed) between
-- events-service's checks and this call makes it return null instead of
-- moving the event. The decision is linked to the submission it answers
-- (E3-4/E1-10) via the latest row in event_safety_submissions for this
-- event — there is exactly one unanswered submission at a time, since a
-- submission only exists while the event is in Safety Review. Returns the
-- new review's id.
create or replace function approve_event_safety_review(
  p_event_id integer,
  p_officer_id text,
  p_reason text
) returns bigint
language plpgsql
as $$
declare
  v_submission_id bigint;
  v_review_id bigint;
begin
  update events
     set status = 'Confirmed'
   where id = p_event_id
     and status = 'Safety Review';
  if not found then
    return null;
  end if;

  select id into v_submission_id
    from event_safety_submissions
   where event_id = p_event_id
   order by submitted_at desc
   limit 1;

  insert into event_safety_reviews (event_id, officer_id, outcome, reason, submission_id)
  values (p_event_id, p_officer_id, 'Approved', p_reason, v_submission_id)
  returning id into v_review_id;

  return v_review_id;
end;
$$;

-- ===== 0029_safety_review_reject.sql =====
-- E3-13: the Safety Officer rejects an event's Operational Safety Check
-- (Safety Review -> Planning). Owned by events-service.
--
-- Guarded so this is safe to re-run.

-- Same shape as approve_event_safety_review (migration 0028): the status
-- change and the decision land together or not at all, and the update
-- only matches while the event is still in Safety Review, so a concurrent
-- decision, re-review or cancellation makes it return null instead of
-- moving the event. A rejection doesn't end the event: it returns to
-- Planning with its venue bookings and equipment reservations untouched,
-- for the coordinator to rework (E3-13 assumption). The reason is
-- required — event_safety_reviews' check constraint refuses a 'Rejected'
-- row without one. Returns the new review's id.
create or replace function reject_event_safety_review(
  p_event_id integer,
  p_officer_id text,
  p_reason text
) returns bigint
language plpgsql
as $$
declare
  v_submission_id bigint;
  v_review_id bigint;
begin
  update events
     set status = 'Planning'
   where id = p_event_id
     and status = 'Safety Review';
  if not found then
    return null;
  end if;

  select id into v_submission_id
    from event_safety_submissions
   where event_id = p_event_id
   order by submitted_at desc
   limit 1;

  insert into event_safety_reviews (event_id, officer_id, outcome, reason, submission_id)
  values (p_event_id, p_officer_id, 'Rejected', p_reason, v_submission_id)
  returning id into v_review_id;

  return v_review_id;
end;
$$;

-- ===== 0030_notifications_messaging.sql =====
-- E7-1 (#61) + ARD section 1.1: columns notification-service needs for
-- "which event" in the feed, and for the RabbitMQ consumer's dedupe (M5).
-- No FK on event_id: events belongs to events-service, same reasoning as
-- recipient_id having no FK to users.

alter table notifications
  add column if not exists event_id int4,
  add column if not exists message_id uuid;

-- One broker message can fan out to several recipients (e.g.
-- coordinator.assigned notifies both the coordinator and the organiser),
-- so several rows legitimately share a message_id — the dedupe key is the
-- pair, not message_id alone.
create unique index if not exists notifications_message_id_recipient_key
  on notifications (message_id, recipient_id)
  where message_id is not null;

create index if not exists notifications_event_id_idx
  on notifications (event_id)
  where event_id is not null;

-- ===== 0031_notifications_audit_fields.sql =====
-- Audit trail for broker-delivered notifications: who caused it and when
-- it actually happened (vs. created_at, which is when the row was
-- inserted — i.e. when the consumer processed the message, which can lag
-- behind occurred_at if the consumer was busy or briefly down).
-- No FK on actor_id: same reasoning as recipient_id/event_id — notification-
-- service doesn't take a hard dependency on another service's table.
-- actor_id is text, matching recipient_id (0017: "users.id (text, e.g.
-- 'COORD-0001')") — user ids in this system are not uuids.

alter table notifications
  add column if not exists actor_id text,
  add column if not exists occurred_at timestamptz;

-- ===== 0032_notifications_actor_id_text.sql =====
-- Corrects 0031: actor_id was declared uuid, but user ids in this system
-- are text (0017: "users.id (text, e.g. 'COORD-0001')"), matching
-- recipient_id. Every real actor_id value (e.g. "LEAD-0001") failed to
-- insert under the uuid type.

alter table notifications
  alter column actor_id type text using actor_id::text;

-- ===== 0033_venue_bookings_expiry_warning.sql =====
-- #106 row 4b: dedupe flag for the new scheduled "hold about to expire"
-- sweep, so it warns a coordinator once per booking rather than every
-- sweep interval.

alter table venue_bookings
  add column if not exists expiry_warning_sent_at timestamptz;

-- ===== 0034_venue_booking_purpose.sql =====
-- E4-17: each venue booking of a (multi-venue) event carries what that
-- venue is for, so suitability is judged per booking — a breakout room
-- against its own session, not the whole event's attendance.
--
--   purpose          — fixed list (lib/bookingPlan.ts BOOKING_PURPOSES);
--                      'Other' needs purpose_detail.
--   headcount        — 1 .. the event's expected attendance (checked by
--                      venue-service, which reads the event through
--                      events-service; the attendance isn't in this table).
--   required_*       — the layouts/facilities/accessibility this booking
--                      needs, pre-filled from the event and editable.
--
-- All nullable: bookings made before E4-17 have none of them, and are read
-- as purpose 'Main programme', headcount = the event's expected attendance
-- and the event's own requirements — exactly what E4-7/E4-8 judged them
-- against. No backfill: the attendance lives in events-service's data.
--
-- Guarded so this is safe to re-run.

alter table venue_bookings add column if not exists purpose text;
alter table venue_bookings add column if not exists purpose_detail text;
alter table venue_bookings add column if not exists headcount integer;
alter table venue_bookings add column if not exists required_layouts text[];
alter table venue_bookings add column if not exists required_facilities text[];
alter table venue_bookings add column if not exists required_accessibility text[];

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'venue_bookings_purpose_check') then
    alter table venue_bookings add constraint venue_bookings_purpose_check
      check (purpose is null or purpose in ('Main programme', 'Breakout', 'Registration', 'Catering', 'Other'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'venue_bookings_purpose_detail_check') then
    alter table venue_bookings add constraint venue_bookings_purpose_detail_check
      check (purpose is distinct from 'Other' or length(btrim(coalesce(purpose_detail, ''))) > 0);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'venue_bookings_headcount_check') then
    alter table venue_bookings add constraint venue_bookings_headcount_check
      check (headcount is null or headcount >= 1);
  end if;
end $$;

-- ===== 0035_safety_review_changes_requested.sql =====
-- E3-14: the Safety Officer requests specific changes to an event's safety
-- arrangements, short of rejecting it (Safety Review -> Planning). Owned by
-- events-service.
--
-- The decision itself is an event_safety_reviews row with outcome
-- 'Changes Requested' (migration 0012 already allows it). What must change
-- is written per flagged arrangement (event_safety_review_flags.note), plus
-- an optional general note for anything that isn't about one arrangement
-- (event_safety_reviews.general_note, added below). The review's reason —
-- required by that table's check constraint — holds them combined
-- ("Label: note; …"), so decision history and notifications read as before.
--
-- A flag points at an arrangement owned by another service (AGENTS.md §1):
-- a venue booking (venue-service's venue_bookings) or an equipment request
-- item (equipment-service's equipment_request_items). So there is no
-- foreign key — only the id, a label for display, and a snapshot of how the
-- arrangement looked when it was flagged. events-service reads the
-- arrangement's current state from its owning service and, when it no
-- longer matches the snapshot, records cleared_at (AC3: "each flag clears
-- when that arrangement is changed"). Once cleared, a flag stays cleared.
--
-- Guarded so this is safe to re-run.

create table if not exists event_safety_review_flags (
  id bigserial primary key,
  review_id bigint not null references event_safety_reviews (id) on delete cascade,
  event_id integer not null references events (id) on delete cascade,
  arrangement_type text not null check (arrangement_type in ('venue_booking', 'equipment_item')),
  arrangement_id bigint not null,
  label text not null,
  -- What must change about this arrangement (required, AC1/AC2).
  note text not null check (length(btrim(note)) > 0),
  snapshot jsonb not null,
  cleared_at timestamptz,
  created_at timestamptz not null default now(),
  unique (review_id, arrangement_type, arrangement_id)
);

-- For a database that ran this file before per-arrangement notes were
-- added: create table above skipped the existing table, so add the note
-- here. Any flag recorded without one is given a placeholder so the
-- not-null and non-empty rules below can hold.
alter table event_safety_review_flags add column if not exists note text;
update event_safety_review_flags set note = 'No note recorded' where note is null or btrim(note) = '';
alter table event_safety_review_flags alter column note set not null;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'event_safety_review_flags_note_check') then
    alter table event_safety_review_flags add constraint event_safety_review_flags_note_check
      check (length(btrim(note)) > 0);
  end if;
end $$;

create index if not exists event_safety_review_flags_event_idx on event_safety_review_flags (event_id);

-- Same stance as the other events-service tables: RLS on, no policies, so
-- only the backend's service-role key reaches it.
alter table event_safety_review_flags enable row level security;

-- Anything the Safety Officer wants changed that isn't about one
-- arrangement. Optional; null for every other outcome.
alter table event_safety_reviews add column if not exists general_note text;

-- Same shape as reject_event_safety_review (migration 0029): the status
-- change, the decision and its flags land together or not at all, and the
-- update only matches while the event is still in Safety Review, so a
-- concurrent decision, re-review or cancellation makes it return null
-- instead of moving the event. Venue bookings and equipment reservations
-- are left as they are, for the coordinator to rework. p_flags is a JSON
-- array of {type, id, label, note, snapshot}; events-service has already
-- checked each one belongs to the event, that there is at least one and
-- that each has a note (AC2). p_reason is the notes combined.
-- Returns the new review's id.
--
-- The earlier version of this function had no p_general_note. A new
-- parameter list makes a second function rather than replacing it, so the
-- old one is dropped first.
drop function if exists request_event_safety_changes(integer, text, text, jsonb);

create or replace function request_event_safety_changes(
  p_event_id integer,
  p_officer_id text,
  p_reason text,
  p_general_note text,
  p_flags jsonb
) returns bigint
language plpgsql
as $$
declare
  v_submission_id bigint;
  v_review_id bigint;
begin
  update events
     set status = 'Planning'
   where id = p_event_id
     and status = 'Safety Review';
  if not found then
    return null;
  end if;

  select id into v_submission_id
    from event_safety_submissions
   where event_id = p_event_id
   order by submitted_at desc
   limit 1;

  insert into event_safety_reviews (event_id, officer_id, outcome, reason, general_note, submission_id)
  values (p_event_id, p_officer_id, 'Changes Requested', p_reason, p_general_note, v_submission_id)
  returning id into v_review_id;

  insert into event_safety_review_flags (review_id, event_id, arrangement_type, arrangement_id, label, note, snapshot)
  select v_review_id,
         p_event_id,
         flag ->> 'type',
         (flag ->> 'id')::bigint,
         flag ->> 'label',
         flag ->> 'note',
         coalesce(flag -> 'snapshot', '{}'::jsonb)
    from jsonb_array_elements(p_flags) as flag;

  return v_review_id;
end;
$$;

-- ===== 0036_change_requests.sql =====
-- E3-9: the Organiser raises a change request once an event is Confirmed,
-- instead of editing it directly (AGENTS.md section 3, "who can edit").
-- E3-8: critical fields (date/time, expected attendance, venue, equipment,
-- accessibility) are held here for the assigned coordinator to decide,
-- rather than applied immediately. Non-critical fields are applied straight
-- to events.submitted_details by events-service and never get a row here.
--
-- Deciding a held request (approve/reject, applying the values, moving the
-- event back to Planning) is E3-11 (#36) and is not implemented by this
-- migration or the route that inserts these rows — decided_by/decided_at/
-- decision_reason exist now so E3-11 needs no follow-up migration.
--
-- Guarded so this is safe to re-run.

do $$ begin
  create type change_request_status as enum ('Pending', 'Approved', 'Rejected');
exception
  when duplicate_object then null;
end $$;

create table if not exists change_requests (
  id bigserial primary key,
  event_id integer not null references events (id) on delete cascade,
  organiser_id text not null,
  status change_request_status not null default 'Pending',
  decided_by text,
  decided_at timestamptz,
  decision_reason text,
  created_at timestamptz not null default now(),
  constraint decision_reason_required_on_reject
    check (status <> 'Rejected' or decision_reason is not null)
);

create table if not exists change_request_fields (
  id bigserial primary key,
  request_id bigint not null references change_requests (id) on delete cascade,
  field text not null,
  old_value text,
  new_value text,
  is_critical boolean not null
);

create index if not exists change_requests_event_id_idx on change_requests (event_id);
create index if not exists change_request_fields_request_id_idx on change_request_fields (request_id);

-- ===== 0037_change_request_merge.sql =====
-- E3-9: while a change request is Pending, a later submission on the same
-- event merges into it instead of piling up a second open request — same
-- field overwrites its held value, a new field is added, and reverting a
-- held field back to its original (committed) value removes it. If that
-- empties out every held field, the request auto-resolves to Approved
-- (nothing left to decide).
--
-- Two constraints enforce the invariants the merge logic depends on:

-- Pre-existing data predates the merge logic: every submission used to
-- create its own row, so an event can already have more than one Pending
-- request. Collapse that before the one-open-per-event index below can be
-- created — keep the most recently created Pending request per event and
-- auto-resolve the rest to Approved (decided_by null), the same
-- "nothing left to decide, system-resolved" treatment the app itself now
-- gives an emptied-out request. Nothing is deleted; only superseded
-- duplicates change status.
with ranked as (
  select id, event_id,
         row_number() over (partition by event_id order by created_at desc, id desc) as rn
  from change_requests
  where status = 'Pending'
)
update change_requests cr
set status = 'Approved', decided_at = now(), decided_by = null
from ranked
where cr.id = ranked.id
  and ranked.rn > 1;

-- Same reason as above: a request could already have more than one row
-- for the same field (each old submission inserted fresh rather than
-- upserting). Keep the most recent one per (request_id, field) — these
-- are just the held-value snapshot, not an audit trail (event_history is
-- that), so it's safe to drop the superseded ones outright.
delete from change_request_fields f
using (
  select id,
         row_number() over (partition by request_id, field order by id desc) as rn
  from change_request_fields
) ranked
where f.id = ranked.id
  and ranked.rn > 1;

-- At most one field row per request — the merge upserts on (request_id,
-- field) rather than ever inserting a duplicate.
create unique index if not exists change_request_fields_request_field_idx
  on change_request_fields (request_id, field);

-- At most one *open* request per event. The route already checks for an
-- existing Pending request before deciding whether to reuse or create one,
-- but that read-then-write has a race window across two concurrent
-- submissions; this is the DB-level backstop (mirrors the "two guards"
-- pattern in venue-service's booking decisions, AGENTS.md section 3a) so
-- two Pending rows for the same event can never coexist.
create unique index if not exists change_requests_one_open_per_event_idx
  on change_requests (event_id)
  where status = 'Pending';

-- ===== 0038_change_request_auto_withdrawn.sql =====
-- E3-9: a request that auto-resolves because every held field was
-- reverted before anyone decided on it was never actually "Approved" —
-- nothing was approved, the request just evaporated. Reusing Approved
-- (plus a text-prefixed decision_reason) to mean that was a stopgap;
-- this gives it its own real status instead.
--
-- Named "Auto-Withdrawn" rather than plain "Withdrawn" because there is no
-- manual withdraw-this-request action anywhere in the system yet — if one
-- is ever built, it gets its own plain "Withdrawn" value then, with no
-- collision. The parallel "Applied automatically" case (a purely
-- non-critical submission) keeps using Approved + decision_reason: unlike
-- this one, "Approved" is actually true there regardless of who/what
-- approved it, and decided_by (null vs set) already tells apart system
-- vs a future coordinator decision (E3-11) — nothing to fix.
--
-- A single statement, alone in its own migration: ALTER TYPE ... ADD
-- VALUE can't safely share a transaction with statements that use the
-- new value (matches migration 0016's precedent for this same enum
-- pattern).
alter type change_request_status add value if not exists 'Auto-Withdrawn';

-- ===== 0039_equipment_request_flag.sql =====
-- E3-11 AC3: when a coordinator approves a held change request whose
-- `equipment` field was touched, the event's equipment requests are
-- flagged so Technical Support knows to reassess them against the
-- organiser's updated wording — nothing about the actual reservation
-- (quantity_fulfilled, item rows) changes automatically (AGENTS.md §1:
-- "no automatic process, has to be done manually").
--
-- Flagged at the request level, not per item: Technical Support reviews
-- the whole request when reassessing, and there's no structural link
-- between the organiser's free-text equipment field and any one item row.
--
-- Guarded so this is safe to re-run.

alter table equipment_requests
  add column if not exists flagged_for_reassessment boolean not null default false,
  add column if not exists flag_reason text,
  add column if not exists flagged_at timestamptz;

-- ===== 0039_registration_period.sql =====
-- Registration period (coordinator sets when registration opens, and can step
-- in manually). Only intent is stored; whether registration is open right now
-- is worked out on every read (events-service lib/registrationPeriod.ts), so
-- opening, closing 5 days before the event, and reopening after a withdrawal
-- need no scheduled job.
--
--   registration_open_date  the day registration opens (Singapore local date).
--                           There is no closing date: by default it closes
--                           5 days before the event starts, or when the event
--                           is full. It always stops when the event starts.
--   registration_override   the coordinator's manual say. NONE follows the
--                           dates; FORCE_OPEN opens it now (even inside the
--                           5-day window); FORCE_CLOSED closes it. Neither
--                           beats the stop at the event start.
alter table public.events
  add column if not exists registration_open_date date,
  add column if not exists registration_override text not null default 'NONE';

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'events_registration_override_check'
  ) then
    alter table public.events
      add constraint events_registration_override_check
      check (registration_override in ('NONE', 'FORCE_OPEN', 'FORCE_CLOSED'));
  end if;
end $$;

-- ===== 0039_venue_buffer_overlaps.sql =====
-- E4-13: "Identify bookings invalidated by setup/turnaround rules".
--
-- AC1 (detection — findBufferOverlaps/findAllBufferOverlaps in
-- venue-service lib/venueChanges.ts) already identifies pairs of bookings
-- whose padded occupied windows now overlap. This table is what AC2/AC3
-- add: a durable, queryable review list so Venue Staff can revisit flagged
-- pairs later, that reconciles itself — a row exists if and only if the
-- pair currently overlaps under the venue's current setup/turnaround and
-- both bookings still block the venue. There is no "dismissed" state and no
-- dismiss action: reconciliation (lib/bufferOverlapReview.ts) is the only
-- thing that inserts or deletes rows here, run from every write path that
-- could change the overlap set (venue edits, withdrawals, booking
-- decisions, event cancellation, venue-unavailability flagging).
--
-- booking_id_a is always the lower of the pair's two booking ids —
-- enforced by the check constraint below and by normalizePair() in
-- lib/venueChanges.ts, which every write path uses before upserting, so the
-- same pair is never stored twice in swapped order.
--
-- window_a/window_b cache formatWindow()'s human-readable description of
-- each side's occupied window at detection time (e.g.
-- "2026-10-12 09:30–12:45"), so GET /venues/:venueId/buffer-overlaps can
-- render the review list without calling events-service on every read.
-- They are deliberately just the display string, not the raw timestamps:
-- nothing here recomputes or re-sorts by them, and the booking's event
-- dates/times (the source of truth) still live in events-service, never
-- in venue-service (AGENTS.md §3a).
--
-- on delete cascade on both FKs: a deleted venue or booking can never leave
-- a dangling flagged row. Neither venues nor venue_bookings rows appear to
-- be hard-deleted by any current code path (bookings move to a terminal
-- status like Withdrawn/Rejected instead), but cascade is the safer
-- default if that ever changes, and it costs nothing while it doesn't.
--
-- Guarded so this is safe to re-run (AGENTS.md: migrations may be edited in
-- place until the first production deploy).

create table if not exists venue_buffer_overlaps (
  id bigserial primary key,
  venue_id integer not null references venues (id) on delete cascade,
  booking_id_a bigint not null references venue_bookings (id) on delete cascade,
  booking_id_b bigint not null references venue_bookings (id) on delete cascade,
  -- Always insert with the lower booking id as booking_id_a (see
  -- normalizePair() in lib/venueChanges.ts) so one unordered pair can never
  -- be stored as two rows.
  constraint venue_buffer_overlaps_ordered check (booking_id_a < booking_id_b),
  -- formatWindow() output for each side at detection time, cached so the
  -- review list doesn't need an events-service round trip to render.
  window_a text not null,
  window_b text not null,
  detected_at timestamptz not null default now(),
  -- Lets reconciliation upsert idempotently: a pair already flagged is left
  -- untouched rather than deleted and re-inserted (AC3: a still-overlapping
  -- pair must not flicker out of the list and back in).
  constraint venue_buffer_overlaps_unique_pair unique (venue_id, booking_id_a, booking_id_b)
);

create index if not exists venue_buffer_overlaps_venue_idx on venue_buffer_overlaps (venue_id);
create index if not exists venue_buffer_overlaps_booking_a_idx on venue_buffer_overlaps (booking_id_a);
create index if not exists venue_buffer_overlaps_booking_b_idx on venue_buffer_overlaps (booking_id_b);

-- Same stance as venues/venue_bookings (0011) and venue_unavailability
-- (0016): RLS on with no policies, so only the backend's service-role key
-- can reach this table.
alter table venue_buffer_overlaps enable row level security;

-- ===== 0040_change_request_partial_approval.sql =====
-- E3-11: the coordinator can approve some held critical fields and reject
-- the rest in the same decision (clarified AC — previously all-or-nothing).
-- The overall change_requests.status stays 'Approved' when at least one
-- field was applied (matches the source clarification: "coordinators
-- approval is still the more important [outcome]"); this column records
-- which held fields, if any, were declined as part of that approval, so
-- the organiser/coordinator can see the split rather than a bare
-- "Approved" that implies everything went through.
--
-- A request that rejects every held field still goes through the existing
-- /reject route (status 'Rejected', unchanged) — this column is only set
-- on a partial approval.

alter table change_requests add column if not exists rejected_fields text[];

-- ===== 0040_register_for_event.sql =====
-- E6: race-safe registration. Two attendees going for the last place used to
-- both pass the count check (the count and the write were separate steps).
-- This function does count + write as one unit, serialised per event with a
-- transaction-level advisory lock keyed on the event id. (An advisory lock,
-- not a lock on the events row, because registration-service owns only the
-- registrations table and never touches events.)
--
-- p_capacity is null for an uncapped event. Returns:
--   'registered'          a new row, or a Withdrawn row back to Registered
--   'already_registered'  the attendee already holds a place
--   'full'                no place left
-- p_set_info = false keeps a returning attendee's earlier additional_info.
create or replace function public.register_for_event(
  p_event_id integer,
  p_user_id text,
  p_capacity integer,
  p_additional_info jsonb,
  p_set_info boolean
) returns text
language plpgsql
as $$
declare
  v_existing_status registration_status;
  v_count integer;
begin
  perform pg_advisory_xact_lock(p_event_id);

  select status into v_existing_status
  from registrations
  where event_id = p_event_id and user_id = p_user_id;

  if v_existing_status = 'Registered' then
    return 'already_registered';
  end if;

  if p_capacity is not null then
    select count(*) into v_count
    from registrations
    where event_id = p_event_id and status = 'Registered';
    if v_count >= p_capacity then
      return 'full';
    end if;
  end if;

  if v_existing_status is null then
    insert into registrations (event_id, user_id, status, additional_info)
    values (p_event_id, p_user_id, 'Registered', p_additional_info);
  else
    update registrations
    set status = 'Registered',
        additional_info = case when p_set_info then p_additional_info else additional_info end
    where event_id = p_event_id and user_id = p_user_id;
  end if;

  return 'registered';
end;
$$;

-- ===== 0041_change_request_field_applied_at.sql =====
-- E3-11: the coordinator can approve held critical fields one subset at a
-- time, leaving the rest open for a later decision instead of forcing an
-- all-or-nothing call. Earlier (migration 0040) this was modelled as
-- deleting an approved field's row immediately, which lost the record of
-- what had already been approved once the request's last remaining field
-- was later decided and the row deleted too — "Changes you decided" would
-- render empty. This column replaces that: an approved field's row stays,
-- stamped with when it applied, so the full history of a multi-step
-- decision survives on the request itself, not just in event_history.
--
-- rejected_fields (0040) is no longer written by the approve route — a
-- field the coordinator doesn't select is just left open, never marked
-- rejected — but the column is left in place rather than dropped, since
-- it's dormant and harmless and this project allows editing migrations
-- in place pre-deploy (AGENTS.md section 5) rather than chasing cleanup
-- migrations for an unused nullable column.

alter table change_request_fields add column if not exists applied_at timestamptz;

-- ===== 0041_registration_cancelled.sql =====
-- E6-4: a registration whose event the organiser cancelled (E3-6) is now
-- 'Cancelled', not 'Withdrawn'. 'Withdrawn' means only that the attendee
-- gave up their own place; 'Cancelled' means the whole event was called off.
-- registration-service's event.cancelled handler writes it.
--
-- `add value if not exists` makes this safe to re-run.

alter type registration_status add value if not exists 'Cancelled';

-- ===== 0042_equipment_amend_cancel.sql =====
-- E5-2: the Event Coordinator amends or cancels an equipment request.
--
-- Both changes move stock and per-unit reservations (equipment_booking), so
-- each is one database function: a request's items, the stock it holds and
-- its reservations can't drift apart half way through. They run in the
-- caller's transaction (PostgREST wraps each request in one), so any
-- exception rolls everything back.
--
-- A request's status stays plain text (migration 0020); this adds a fourth
-- value, 'Cancelled' — the coordinator withdrew the whole request. The row
-- and its items stay as history; nothing is reserved against it any more.
-- Technical Support never sees a Cancelled request in their queue.
--
-- Guarded (create or replace) so this is safe to re-run.

-- Amends a request in place. p_items is the request's full new item list, a
-- jsonb array of {"itemId": <existing item id, absent for a new item>,
-- "equipmentCatalogId": ..., "equipmentType": <catalog name>, "quantity": ...}.
-- Existing items missing from the list are removed.
--
--   * quantity lowered below what is reserved -> the surplus is released:
--     stock returns to equipment_catalog and that many equipment_booking
--     rows are deleted (AC2).
--   * type changed -> everything reserved of the old type is released and
--     the item starts unreserved as the new type.
--   * item removed -> everything reserved against it is released.
--   * quantity raised, or a new item -> nothing is reserved automatically;
--     Technical Support arrange it.
--
-- Only a 'Requested' or 'Partially Fulfilled' request can be amended. The
-- status is then recomputed from what is still reserved (nothing -> Requested,
-- everything -> Arranged, otherwise Partially Fulfilled), so an amended
-- request never claims more than it holds.
--
-- Returns {"status": ..., "changes": [...]} where each change is
-- {"kind": "quantity"|"type"|"added"|"removed", "equipmentType", "fromType"?,
--  "from"?, "to"?, "quantity"?, "released"}.
create or replace function amend_equipment_request(p_request_id bigint, p_items jsonb)
returns jsonb
language plpgsql
as $$
declare
  req_status text;
  item record;
  spec jsonb;
  new_qty integer;
  new_catalog bigint;
  new_type text;
  surplus integer;
  total_fulfilled integer;
  all_met boolean;
  new_status text;
  changes jsonb := '[]'::jsonb;
begin
  select status into req_status from equipment_requests where id = p_request_id for update;
  if not found then
    raise exception 'Equipment request not found: %', p_request_id;
  end if;
  if req_status not in ('Requested', 'Partially Fulfilled') then
    raise exception 'Equipment request cannot be amended: %', req_status;
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'At least one item is required';
  end if;

  if exists (
    select 1 from jsonb_array_elements(p_items) as e(v)
    where e.v->>'itemId' is not null
      and not exists (
        select 1 from equipment_request_items i
        where i.id = (e.v->>'itemId')::bigint and i.request_id = p_request_id
      )
  ) then
    raise exception 'Unknown item in amendment';
  end if;

  for item in
    select id, equipment_type, quantity, quantity_fulfilled, equipment_catalog_id
    from equipment_request_items
    where request_id = p_request_id
    order by equipment_catalog_id, id
  loop
    select e.v into spec
    from jsonb_array_elements(p_items) as e(v)
    where (e.v->>'itemId')::bigint = item.id
    limit 1;

    if spec is null then
      -- Removed: give back everything it held. Its equipment_booking rows go
      -- with it (on delete cascade, migration 0027).
      if item.quantity_fulfilled > 0 and item.equipment_catalog_id is not null then
        update equipment_catalog
          set available_stock = available_stock + item.quantity_fulfilled
          where id = item.equipment_catalog_id;
      end if;
      delete from equipment_request_items where id = item.id;
      changes := changes || jsonb_build_object(
        'kind', 'removed',
        'equipmentType', item.equipment_type,
        'quantity', item.quantity,
        'released', item.quantity_fulfilled
      );
      continue;
    end if;

    new_qty := (spec->>'quantity')::integer;
    new_catalog := (spec->>'equipmentCatalogId')::bigint;
    new_type := spec->>'equipmentType';

    if new_catalog is distinct from item.equipment_catalog_id then
      if item.quantity_fulfilled > 0 and item.equipment_catalog_id is not null then
        update equipment_catalog
          set available_stock = available_stock + item.quantity_fulfilled
          where id = item.equipment_catalog_id;
      end if;
      delete from equipment_booking where request_item_id = item.id;
      update equipment_request_items
        set equipment_catalog_id = new_catalog,
            equipment_type = new_type,
            quantity = new_qty,
            quantity_fulfilled = 0
        where id = item.id;
      changes := changes || jsonb_build_object(
        'kind', 'type',
        'fromType', item.equipment_type,
        'equipmentType', new_type,
        'from', item.quantity,
        'to', new_qty,
        'released', item.quantity_fulfilled
      );
    elsif new_qty <> item.quantity then
      surplus := greatest(0, item.quantity_fulfilled - new_qty);
      if surplus > 0 then
        if item.equipment_catalog_id is not null then
          update equipment_catalog
            set available_stock = available_stock + surplus
            where id = item.equipment_catalog_id;
        end if;
        delete from equipment_booking
          where id in (
            select id from equipment_booking
            where request_item_id = item.id
            order by id
            limit surplus
          );
      end if;
      update equipment_request_items
        set quantity = new_qty,
            quantity_fulfilled = least(item.quantity_fulfilled, new_qty)
        where id = item.id;
      changes := changes || jsonb_build_object(
        'kind', 'quantity',
        'equipmentType', item.equipment_type,
        'from', item.quantity,
        'to', new_qty,
        'released', surplus
      );
    end if;
  end loop;

  for spec in
    select e.v from jsonb_array_elements(p_items) as e(v) where e.v->>'itemId' is null
  loop
    insert into equipment_request_items (request_id, equipment_catalog_id, equipment_type, quantity)
    values (
      p_request_id,
      (spec->>'equipmentCatalogId')::bigint,
      spec->>'equipmentType',
      (spec->>'quantity')::integer
    );
    changes := changes || jsonb_build_object(
      'kind', 'added',
      'equipmentType', spec->>'equipmentType',
      'quantity', (spec->>'quantity')::integer,
      'released', 0
    );
  end loop;

  select coalesce(sum(quantity_fulfilled), 0), coalesce(bool_and(quantity_fulfilled >= quantity), false)
    into total_fulfilled, all_met
    from equipment_request_items
    where request_id = p_request_id;

  if total_fulfilled = 0 then
    new_status := 'Requested';
  elsif all_met then
    new_status := 'Arranged';
  else
    new_status := 'Partially Fulfilled';
  end if;

  update equipment_requests
    set status = new_status,
        fulfillment_note = case when new_status = 'Partially Fulfilled' then fulfillment_note else null end
    where id = p_request_id;

  return jsonb_build_object('status', new_status, 'changes', changes);
end;
$$;

-- Cancels a request entirely (AC3): releases everything reserved against it
-- (stock back to equipment_catalog, its equipment_booking rows deleted) and
-- marks it 'Cancelled'. The items stay, unreserved, as history. Mirrors
-- release_equipment_for_event (migration 0027), but for one request.
--
-- Returns {"released": [{"equipmentType": ..., "quantity": ...}]} — only the
-- items that actually held something.
create or replace function release_equipment_for_request(p_request_id bigint)
returns jsonb
language plpgsql
as $$
declare
  req_status text;
  item record;
  released jsonb := '[]'::jsonb;
begin
  select status into req_status from equipment_requests where id = p_request_id for update;
  if not found then
    raise exception 'Equipment request not found: %', p_request_id;
  end if;
  if req_status = 'Cancelled' then
    raise exception 'Equipment request already cancelled: %', p_request_id;
  end if;

  for item in
    select id, equipment_type, quantity_fulfilled, equipment_catalog_id
    from equipment_request_items
    where request_id = p_request_id
    order by equipment_catalog_id, id
  loop
    if item.quantity_fulfilled > 0 then
      if item.equipment_catalog_id is not null then
        update equipment_catalog
          set available_stock = available_stock + item.quantity_fulfilled
          where id = item.equipment_catalog_id;
      end if;
      released := released || jsonb_build_object(
        'equipmentType', item.equipment_type,
        'quantity', item.quantity_fulfilled
      );
      update equipment_request_items set quantity_fulfilled = 0 where id = item.id;
    end if;
    delete from equipment_booking where request_item_id = item.id;
  end loop;

  update equipment_requests
    set status = 'Cancelled', fulfillment_note = null
    where id = p_request_id;

  return jsonb_build_object('released', released);
end;
$$;

-- ===== 0043_equipment_unavailability.sql =====
-- E5-5: Technical Support mark a physical equipment unit damaged or under
-- maintenance for a period, so it stops being offered to events.
--
-- equipment.status (migration 0025) says only whether a unit is usable right
-- now, with no dates, and nothing in the app could change it. A period lets
-- Technical Support say "out from 3 Nov to 7 Nov", or "out from 3 Nov until
-- it's repaired" (no end date). Availability checks (E5-4) and reservations
-- (E5-6) skip a unit whenever one of its periods overlaps the event's date.
-- equipment.status keeps its old meaning — unusable indefinitely — so units
-- already set to Damaged or Under Maintenance stay excluded.
--
-- start_date and end_date are inclusive local calendar dates, like venue
-- block-outs (migration 0016). A null end_date means "until marked usable
-- again", which deletes the row.
--
-- Guarded so this is safe to re-run.

create table if not exists equipment_unavailability (
  id bigint generated by default as identity primary key,
  equipment_id bigint not null references equipment (id) on delete cascade,
  reason text not null check (reason in ('Damaged', 'Under Maintenance')),
  start_date date not null,
  end_date date,
  note text,
  marked_by text references users (id),
  created_at timestamptz not null default now(),
  constraint equipment_unavailability_dates_check check (end_date is null or end_date >= start_date)
);

create index if not exists equipment_unavailability_equipment_idx on equipment_unavailability (equipment_id);

-- Same stance as every other table since migration 0004: RLS on with no
-- policies, so only the backend's service-role key can reach this.
alter table equipment_unavailability enable row level security;

-- ===== 0044_equipment_stock_changes.sql =====
-- E5-5 follow-up: equipment stock is changed deliberately, with a reason.
--
-- Until now Technical Support could overwrite an item's total and available
-- stock directly (E5-1). Available stock is derived — request statuses move it
-- as equipment is reserved and released — and the total no longer matched the
-- per-unit rows in `equipment` once units could be marked unusable (migration
-- 0043). Now:
--   * available stock is never edited by hand;
--   * the total changes only through change_equipment_stock(), which adds or
--     removes the matching unit rows in the same step, needs a reason, and
--     records the change in equipment_stock_changes.
--
-- equipment.label is an optional tag for a physical unit (e.g. the sticker
-- number on it), so "Projector #12" can be matched to the real item.
--
-- Guarded so this is safe to re-run.

alter table equipment add column if not exists label text;

create table if not exists equipment_stock_changes (
  id bigint generated by default as identity primary key,
  equipment_catalog_id bigint not null references equipment_catalog (id) on delete cascade,
  change_type text not null check (change_type in ('Added', 'Removed')),
  quantity integer not null check (quantity > 0),
  total_before integer not null,
  total_after integer not null,
  reason text not null,
  changed_by text references users (id),
  created_at timestamptz not null default now()
);

create index if not exists equipment_stock_changes_item_idx
  on equipment_stock_changes (equipment_catalog_id, created_at desc);

-- Same stance as every other table since migration 0004: RLS on with no
-- policies, so only the backend's service-role key can reach this.
alter table equipment_stock_changes enable row level security;

-- Adds (p_delta > 0) or removes (p_delta < 0) stock of one catalog item.
--
--   * Adding creates p_delta Available unit rows and raises both total and
--     available stock by that many.
--   * Removing deletes p_delta unit rows and lowers both counters. It only ever
--     removes units that are Available, hold no reservation and have no running
--     or upcoming unusable period, so it can never pull equipment out from under
--     an event; and it can't take more than the catalog's available stock. If
--     fewer than p_delta units qualify it raises 'Cannot remove N: only M can be
--     removed' and changes nothing.
--
-- p_reason is required. Runs in the caller's transaction (PostgREST wraps each
-- request in one), so any exception rolls the whole change back.
create or replace function change_equipment_stock(
  p_catalog_id bigint,
  p_delta integer,
  p_reason text,
  p_user text
)
returns jsonb
language plpgsql
as $$
declare
  cat record;
  free_ids bigint[];
  removable integer;
  wanted integer;
  new_total integer;
  new_available integer;
begin
  if p_delta is null or p_delta = 0 then
    raise exception 'Quantity must be at least 1';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'A reason is required';
  end if;

  select id, name, total_stock, available_stock into cat
    from equipment_catalog where id = p_catalog_id for update;
  if not found then
    raise exception 'Equipment item not found: %', p_catalog_id;
  end if;

  if p_delta > 0 then
    insert into equipment (type, status)
      select cat.name, 'Available' from generate_series(1, p_delta);
  else
    wanted := -p_delta;
    select coalesce(array_agg(s.id), '{}') into free_ids from (
      select e.id
      from equipment e
      where e.type = cat.name
        and e.status = 'Available'
        and not exists (select 1 from equipment_booking b where b.equipment_id = e.id)
        and not exists (
          select 1 from equipment_unavailability u
          where u.equipment_id = e.id and (u.end_date is null or u.end_date >= current_date)
        )
      order by e.id desc
      limit wanted
    ) s;

    removable := least(coalesce(array_length(free_ids, 1), 0), cat.available_stock);
    if removable < wanted then
      raise exception 'Cannot remove %: only % can be removed', wanted, removable;
    end if;

    delete from equipment where id = any(free_ids);
  end if;

  new_total := cat.total_stock + p_delta;
  new_available := cat.available_stock + p_delta;
  update equipment_catalog
    set total_stock = new_total, available_stock = new_available
    where id = cat.id;

  insert into equipment_stock_changes
    (equipment_catalog_id, change_type, quantity, total_before, total_after, reason, changed_by)
  values
    (cat.id, case when p_delta > 0 then 'Added' else 'Removed' end, abs(p_delta),
     cat.total_stock, new_total, btrim(p_reason), p_user);

  return jsonb_build_object(
    'id', cat.id,
    'name', cat.name,
    'totalStock', new_total,
    'availableStock', new_available
  );
end;
$$;

-- ===== 0045_event_outbox.sql =====
-- Reliable publishing of action messages (events-service).
--
-- A message another service must act on (today: event.cancelled, which
-- venue-, equipment- and registration-service react to) is stored here in
-- the same request that changes the event, then published to RabbitMQ.
-- If the broker is down or the service restarts first, a relay in
-- events-service keeps retrying the rows with published_at still null, in
-- id order, until the broker confirms them. Delivery is at-least-once:
-- message_id is stable across retries, so a consumer that has already
-- handled it can skip the repeat.
--
-- Owned by events-service only (AGENTS.md section 1). Guarded so this is
-- safe to re-run.

create table if not exists event_outbox (
  id bigint generated by default as identity primary key,
  message_id uuid not null unique default gen_random_uuid(),
  type text not null,
  event_id bigint,
  actor_id text,
  recipients jsonb not null default '{"userIds": [], "roles": []}'::jsonb,
  data jsonb not null default '{}'::jsonb,
  occurred_at timestamptz not null default now(),
  published_at timestamptz,
  attempts integer not null default 0,
  last_error text,
  created_at timestamptz not null default now()
);

-- The relay only ever looks at what is still unpublished.
create index if not exists event_outbox_pending_idx on event_outbox (id) where published_at is null;

alter table event_outbox enable row level security;

-- ===== 0046_needs_review_status.sql =====
-- "Needs Review": the status a Confirmed event moves to when something it
-- relied on changes after safety approval — a venue booking becomes
-- Replacement Required, a reserved equipment unit becomes unusable, or the
-- Organiser raises a change request holding critical fields. Owned by
-- events-service. See AGENTS.md section 3.
--
-- Why a status and not Planning: Planning is where an event is built before
-- it has been safety-approved. A Confirmed event that loses its venue is
-- already approved, so the coordinator needs somewhere to re-arrange it
-- without the event reading as "back to the start" (and without the venue,
-- equipment and change-request routes being gated on Planning alone).
--
-- safety_approval_stale: true once anything the Safety Officer approved has
-- changed (an arrangement was lost, or a change request was approved). While
-- false, Needs Review is only waiting on a change-request decision, so a
-- rejected request can return the event straight to Confirmed. While true,
-- the event must pass Safety Review again. Cleared on every submission.
--
-- Guarded so this is safe to re-run. The new value is only referenced as a
-- string inside the function body, which Postgres does not resolve until it
-- runs, so this works in one script.

alter type event_status add value if not exists 'Needs Review' after 'Confirmed';

alter table events add column if not exists safety_approval_stale boolean not null default false;

-- Same as 0026, but a coordinator may also submit from Needs Review.
create or replace function submit_event_for_safety_review(
  p_event_id integer,
  p_submitted_by text,
  p_equipment_placement text,
  p_crowd_movement text,
  p_emergency_access text,
  p_venue_restrictions text
) returns bigint
language plpgsql
as $$
declare
  v_submission_id bigint;
begin
  update events
     set status = 'Safety Review',
         safety_approval_stale = false
   where id = p_event_id
     and status::text in ('Planning', 'Needs Review')
     and coordinator_id = p_submitted_by;
  if not found then
    return null;
  end if;

  insert into event_safety_submissions (
    event_id, submitted_by, equipment_placement, crowd_movement, emergency_access, venue_restrictions
  ) values (
    p_event_id, p_submitted_by, p_equipment_placement, p_crowd_movement, p_emergency_access, p_venue_restrictions
  )
  returning id into v_submission_id;

  return v_submission_id;
end;
$$;

-- ===== 0047_booking_cancelled_status.sql =====
-- "Cancelled": a venue booking the system cancelled because its venue became
-- unavailable (Venue Staff added a block-out period over an Approved booking,
-- Week 7 change 2). Owned by venue-service. See AGENTS.md section 3a.
--
-- Not the same as the other end states: Rejected is Venue Staff refusing a
-- request, Withdrawn is the coordinator giving a booking up, Expired is a hold
-- that lapsed. Cancelled is nobody's choice, so decided_by stays null and
-- decision_reason holds why (the venue and the block-out reason). The event is
-- not cancelled; its coordinator searches for a replacement venue.
--
-- Guarded so this is safe to re-run.

alter type venue_booking_status add value if not exists 'Cancelled';

-- ===== 0048_equipment_unit_catalog_link.sql =====
-- Links every equipment unit to its catalog item by id, not by matching names.
--
-- Until now an `equipment` row belonged to a catalog item only because its
-- `type` text happened to equal `equipment_catalog.name`, and a request item's
-- `equipment_catalog_id` was optional. Nothing stopped the two drifting apart,
-- and anything computed per catalog item (stock, availability) had to join on
-- text. Now:
--   * equipment.equipment_catalog_id points at the catalog item;
--   * request items must have one too;
--   * change_equipment_stock() finds and creates units by that id.
-- `equipment.type` stays for now (still written, no longer used to look units up),
-- so the API's `type` field keeps working unchanged.
--
-- Guarded so this is safe to re-run. NOT NULL is only applied when every
-- existing row could be linked; otherwise it raises a notice and leaves the
-- column nullable so the rows can be fixed by hand first.

alter table equipment
  add column if not exists equipment_catalog_id bigint references equipment_catalog (id);

update equipment e
set equipment_catalog_id = c.id
from equipment_catalog c
where e.equipment_catalog_id is null and c.name = e.type;

update equipment_request_items i
set equipment_catalog_id = c.id
from equipment_catalog c
where i.equipment_catalog_id is null and c.name = i.equipment_type;

create index if not exists equipment_catalog_status_idx on equipment (equipment_catalog_id, status);

do $$
begin
  if exists (select 1 from equipment where equipment_catalog_id is null) then
    raise notice 'equipment: some units match no catalog item; equipment_catalog_id left nullable. Fix: select id, type from equipment where equipment_catalog_id is null;';
  else
    alter table equipment alter column equipment_catalog_id set not null;
  end if;

  if exists (select 1 from equipment_request_items where equipment_catalog_id is null) then
    raise notice 'equipment_request_items: some items match no catalog item; equipment_catalog_id left nullable. Fix: select id, equipment_type from equipment_request_items where equipment_catalog_id is null;';
  else
    alter table equipment_request_items alter column equipment_catalog_id set not null;
  end if;
end
$$;

-- change_equipment_stock (0044), now finding and creating units by catalog id.
create or replace function change_equipment_stock(
  p_catalog_id bigint,
  p_delta integer,
  p_reason text,
  p_user text
)
returns jsonb
language plpgsql
as $$
declare
  cat record;
  free_ids bigint[];
  removable integer;
  wanted integer;
  new_total integer;
  new_available integer;
begin
  if p_delta is null or p_delta = 0 then
    raise exception 'Quantity must be at least 1';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'A reason is required';
  end if;

  select id, name, total_stock, available_stock into cat
    from equipment_catalog where id = p_catalog_id for update;
  if not found then
    raise exception 'Equipment item not found: %', p_catalog_id;
  end if;

  if p_delta > 0 then
    insert into equipment (type, status, equipment_catalog_id)
      select cat.name, 'Available', cat.id from generate_series(1, p_delta);
  else
    wanted := -p_delta;
    select coalesce(array_agg(s.id), '{}') into free_ids from (
      select e.id
      from equipment e
      where e.equipment_catalog_id = cat.id
        and e.status = 'Available'
        and not exists (select 1 from equipment_booking b where b.equipment_id = e.id)
        and not exists (
          select 1 from equipment_unavailability u
          where u.equipment_id = e.id and (u.end_date is null or u.end_date >= current_date)
        )
      order by e.id desc
      limit wanted
    ) s;

    removable := least(coalesce(array_length(free_ids, 1), 0), cat.available_stock);
    if removable < wanted then
      raise exception 'Cannot remove %: only % can be removed', wanted, removable;
    end if;

    delete from equipment where id = any(free_ids);
  end if;

  new_total := cat.total_stock + p_delta;
  new_available := cat.available_stock + p_delta;
  update equipment_catalog
    set total_stock = new_total, available_stock = new_available
    where id = cat.id;

  insert into equipment_stock_changes
    (equipment_catalog_id, change_type, quantity, total_before, total_after, reason, changed_by)
  values
    (cat.id, case when p_delta > 0 then 'Added' else 'Removed' end, abs(p_delta),
     cat.total_stock, new_total, btrim(p_reason), p_user);

  return jsonb_build_object(
    'id', cat.id,
    'name', cat.name,
    'totalStock', new_total,
    'availableStock', new_available
  );
end;
$$;

-- ===== 0049_reserve_equipment_request.sql =====
-- Reserving equipment as one step.
--
-- Moving a request to Arranged / Partially Fulfilled (E5-3, E5-6) used to be
-- three separate database calls from the application: pick free units, move
-- the stock counters (apply_equipment_request_status, 0022), then write the
-- equipment_booking rows. If the last step failed, the counters had already
-- moved and the code tried to undo them with a second call. This function does
-- all of it in one transaction, so a failure anywhere leaves nothing changed.
--
-- Which units are free for the event's dates is still decided by the
-- application, because event times live in events-service and the database
-- holds no dates. The application passes the units it chose in p_claims
-- ([{"itemId": 1, "unitIds": [201, 202]}], one entry per item whose reserved
-- quantity grows). What this function can check, and does, is what the
-- database knows: each unit exists, is the right equipment item, is still
-- 'Available', and is not already reserved for this same event. It does NOT
-- refuse a unit that is reserved for another event, since the same unit may be
-- used on different days. A shrinking item releases its oldest bookings.
--
-- Raises (and so rolls everything back):
--   'Not enough stock ...'                  from apply_equipment_request_status
--   'Unit N is no longer available'         the unit was marked unusable meanwhile
--   'Unit N is already reserved for this event'
--   'Unit N is not the requested equipment type'
--   'Item N needs X units but Y were chosen' / 'No units were chosen for item N'
--
-- Guarded so this is safe to re-run.

create or replace function reserve_equipment_request(
  p_request_id bigint,
  p_status text,
  p_note text,
  p_fulfillments jsonb default '[]'::jsonb,
  p_claims jsonb default '[]'::jsonb
)
returns void
language plpgsql
as $$
declare
  req record;
  before_fulfilled jsonb;
  item record;
  claim jsonb;
  claimed bigint[];
  delta integer;
  unit record;
  found_units integer;
begin
  select id, event_id into req from equipment_requests where id = p_request_id for update;
  if not found then
    raise exception 'Equipment request not found: %', p_request_id;
  end if;

  -- What each item held before, to tell how many units to claim or release.
  select coalesce(jsonb_object_agg(id::text, quantity_fulfilled), '{}'::jsonb)
    into before_fulfilled
    from equipment_request_items
    where request_id = p_request_id;

  -- The stock counters and the request status (0022). Raises if there is not enough stock.
  perform apply_equipment_request_status(p_request_id, p_status, p_note, p_fulfillments);

  for item in
    select id, equipment_catalog_id, quantity_fulfilled
    from equipment_request_items
    where request_id = p_request_id
    order by id
  loop
    delta := item.quantity_fulfilled - coalesce((before_fulfilled ->> item.id::text)::integer, 0);

    if delta < 0 then
      delete from equipment_booking
      where id in (
        select id from equipment_booking where request_item_id = item.id order by id limit -delta
      );

    elsif delta > 0 then
      select e.c into claim
        from jsonb_array_elements(p_claims) as e(c)
        where (e.c ->> 'itemId')::bigint = item.id
        limit 1;
      if claim is null then
        raise exception 'No units were chosen for item %', item.id;
      end if;

      select coalesce(array_agg(t.value::bigint), '{}') into claimed
        from jsonb_array_elements_text(claim -> 'unitIds') as t(value);
      if (select count(distinct x) from unnest(claimed) as x) <> delta
         or coalesce(array_length(claimed, 1), 0) <> delta then
        raise exception 'Item % needs % units but % were chosen', item.id, delta, coalesce(array_length(claimed, 1), 0);
      end if;

      -- Lock the units so two reservations of the same unit run one after the other.
      found_units := 0;
      for unit in
        select id, equipment_catalog_id, status
        from equipment
        where id = any(claimed)
        order by id
        for update
      loop
        found_units := found_units + 1;
        if unit.equipment_catalog_id is distinct from item.equipment_catalog_id then
          raise exception 'Unit % is not the requested equipment type', unit.id;
        end if;
        if unit.status <> 'Available' then
          raise exception 'Unit % is no longer available', unit.id;
        end if;
        if exists (
          select 1 from equipment_booking b where b.equipment_id = unit.id and b.event_id = req.event_id
        ) then
          raise exception 'Unit % is already reserved for this event', unit.id;
        end if;
      end loop;
      if found_units <> delta then
        raise exception 'Unknown equipment unit in the claim for item %', item.id;
      end if;

      insert into equipment_booking (equipment_id, event_id, request_item_id)
        select u, req.event_id, item.id from unnest(claimed) as u;
    end if;
  end loop;
end;
$$;

-- ===== 0050_equipment_booking_windows.sql =====
-- Reserving equipment: the database now refuses overlapping dates.
--
-- 0049 made a reservation one transaction, but it could not tell whether a unit
-- was already booked for ANOTHER event on overlapping dates, because
-- equipment_booking stored no dates (they live in events-service). So two
-- coordinators picking the last unit for overlapping events at the same moment
-- could both succeed. It also did not check equipment_unavailability, so a unit
-- marked damaged for those dates between "chosen" and "reserved" still booked.
--
-- Now every booking stores the window it holds, as epoch milliseconds in the
-- same wall-clock-read-as-UTC form as the application's occupiedWindow()
-- (equipment-service lib/scheduleWindow.ts), so the two always compare equal.
-- reserve_equipment_request takes the event's window from the application,
-- locks the units, and then refuses:
--   'Unit N is already booked for overlapping dates'
--   'Unit N is unavailable during these dates'      (an equipment_unavailability period)
-- Both run after the row lock, so of two simultaneous reservations the second
-- waits, then sees the first's booking and is refused.
--
-- Bookings made before this migration have no stored window (NULL). The
-- database cannot invent one, so it skips them; the application still checks
-- them against events-service, and writes each window back as it resolves it
-- (lib/equipmentConflicts.ts), so they fill in over time. The window is also
-- refreshed there when an event is rescheduled, so a stored window can lag a
-- reschedule only until the unit is next checked.
--
-- Guarded so this is safe to re-run.

alter table equipment_booking add column if not exists window_start_ms bigint;
alter table equipment_booking add column if not exists window_end_ms bigint;

create index if not exists equipment_booking_window_idx on equipment_booking (equipment_id, window_start_ms, window_end_ms);

-- The signature changes, so the 0049 version must go or both would exist.
drop function if exists reserve_equipment_request(bigint, text, text, jsonb, jsonb);

create or replace function reserve_equipment_request(
  p_request_id bigint,
  p_status text,
  p_note text,
  p_fulfillments jsonb default '[]'::jsonb,
  p_claims jsonb default '[]'::jsonb,
  p_window_start_ms bigint default null,
  p_window_end_ms bigint default null
)
returns void
language plpgsql
as $$
declare
  req record;
  before_fulfilled jsonb;
  item record;
  claim jsonb;
  claimed bigint[];
  delta integer;
  unit record;
  found_units integer;
  first_day date;
  last_day date;
begin
  select id, event_id into req from equipment_requests where id = p_request_id for update;
  if not found then
    raise exception 'Equipment request not found: %', p_request_id;
  end if;

  -- What each item held before, to tell how many units to claim or release.
  select coalesce(jsonb_object_agg(id::text, quantity_fulfilled), '{}'::jsonb)
    into before_fulfilled
    from equipment_request_items
    where request_id = p_request_id;

  -- The stock counters and the request status (0022). Raises if there is not enough stock.
  perform apply_equipment_request_status(p_request_id, p_status, p_note, p_fulfillments);

  for item in
    select id, equipment_catalog_id, quantity_fulfilled
    from equipment_request_items
    where request_id = p_request_id
    order by id
  loop
    delta := item.quantity_fulfilled - coalesce((before_fulfilled ->> item.id::text)::integer, 0);

    if delta < 0 then
      delete from equipment_booking
      where id in (
        select id from equipment_booking where request_item_id = item.id order by id limit -delta
      );

    elsif delta > 0 then
      select e.c into claim
        from jsonb_array_elements(p_claims) as e(c)
        where (e.c ->> 'itemId')::bigint = item.id
        limit 1;
      if claim is null then
        raise exception 'No units were chosen for item %', item.id;
      end if;

      if p_window_start_ms is null or p_window_end_ms is null or p_window_end_ms <= p_window_start_ms then
        raise exception 'The event window is required to reserve item %', item.id;
      end if;
      -- Whole days the window touches, for comparing with unavailability periods
      -- (end is exclusive, so the last day is the one holding end - 1 ms).
      first_day := (to_timestamp(p_window_start_ms / 1000.0) at time zone 'UTC')::date;
      last_day := (to_timestamp((p_window_end_ms - 1) / 1000.0) at time zone 'UTC')::date;

      select coalesce(array_agg(t.value::bigint), '{}') into claimed
        from jsonb_array_elements_text(claim -> 'unitIds') as t(value);
      if (select count(distinct x) from unnest(claimed) as x) <> delta
         or coalesce(array_length(claimed, 1), 0) <> delta then
        raise exception 'Item % needs % units but % were chosen', item.id, delta, coalesce(array_length(claimed, 1), 0);
      end if;

      -- Lock the units so two reservations of the same unit run one after the other.
      found_units := 0;
      for unit in
        select id, equipment_catalog_id, status
        from equipment
        where id = any(claimed)
        order by id
        for update
      loop
        found_units := found_units + 1;
        if unit.equipment_catalog_id is distinct from item.equipment_catalog_id then
          raise exception 'Unit % is not the requested equipment type', unit.id;
        end if;
        if unit.status <> 'Available' then
          raise exception 'Unit % is no longer available', unit.id;
        end if;
        if exists (
          select 1 from equipment_booking b where b.equipment_id = unit.id and b.event_id = req.event_id
        ) then
          raise exception 'Unit % is already reserved for this event', unit.id;
        end if;
        if exists (
          select 1 from equipment_booking b
          where b.equipment_id = unit.id
            and b.window_start_ms is not null
            and b.window_start_ms < p_window_end_ms
            and p_window_start_ms < b.window_end_ms
        ) then
          raise exception 'Unit % is already booked for overlapping dates', unit.id;
        end if;
        if exists (
          select 1 from equipment_unavailability u
          where u.equipment_id = unit.id
            and u.start_date <= last_day
            and (u.end_date is null or u.end_date >= first_day)
        ) then
          raise exception 'Unit % is unavailable during these dates', unit.id;
        end if;
      end loop;
      if found_units <> delta then
        raise exception 'Unknown equipment unit in the claim for item %', item.id;
      end if;

      insert into equipment_booking (equipment_id, event_id, request_item_id, window_start_ms, window_end_ms)
        select u, req.event_id, item.id, p_window_start_ms, p_window_end_ms from unnest(claimed) as u;
    end if;
  end loop;
end;
$$;

-- ===== 0051_stop_using_stock_counters.sql =====
-- Stop using the stock counters (equipment_catalog.total_stock and
-- available_stock) and compute stock from the unit rows and their bookings.
--
-- The counters were a date-blind running total: reserving a unit for any event,
-- on any day, took one off available_stock, so an item with N units could back
-- at most N reservations across all events however far apart, and the
-- availability page subtracted reserved units twice (once in the counter, once
-- as "reserved elsewhere"). Whether a unit is free is a per-unit, per-date
-- question that equipment_booking's stored windows (0050) can already answer.
--
-- From here:
--   total      = the number of unit rows for the catalog item;
--   available  = units that are Available, have no unusable period today and
--                no booking whose window overlaps today (catalog_stock_now);
--   a reservation is refused by the per-unit checks in reserve_equipment_request
--   (type, status, booked for overlapping dates, unavailable during these
--   dates), not by a counter, so "Not enough stock" is no longer raised.
--
-- equipment_request_items.quantity_fulfilled is still written: it is the
-- request's own record of how many Technical Support marked fulfilled, which the
-- routes and the API use. The stock counters are simply no longer read or
-- written. The columns stay until migration 0052 drops them, so this can be
-- rolled back by redeploying the previous functions.
--
-- Guarded (create or replace) so this is safe to re-run.

create or replace function apply_equipment_request_status(
  p_request_id bigint,
  p_status text,
  p_note text,
  p_fulfillments jsonb default '[]'::jsonb
)
returns void
language plpgsql
as $$
declare
  item record;
  target_fulfilled integer;
begin
  if p_status not in ('Requested', 'Arranged', 'Partially Fulfilled') then
    raise exception 'Invalid status: %', p_status;
  end if;

  if not exists (select 1 from equipment_requests where id = p_request_id for update) then
    raise exception 'Equipment request not found: %', p_request_id;
  end if;

  for item in
    select id, quantity, quantity_fulfilled, equipment_catalog_id
    from equipment_request_items
    where request_id = p_request_id
    order by equipment_catalog_id, id
  loop
    if p_status = 'Requested' then
      target_fulfilled := 0;
    elsif p_status = 'Arranged' then
      target_fulfilled := item.quantity;
    else
      select (elem->>'fulfilledQuantity')::integer into target_fulfilled
      from jsonb_array_elements(p_fulfillments) elem
      where (elem->>'itemId')::bigint = item.id;

      if target_fulfilled is null then
        raise exception 'Missing fulfilled quantity for item %', item.id;
      end if;
      if target_fulfilled < 0 or target_fulfilled > item.quantity then
        raise exception 'Fulfilled quantity for item % must be between 0 and %', item.id, item.quantity;
      end if;
    end if;

    update equipment_request_items
      set quantity_fulfilled = target_fulfilled
      where id = item.id;
  end loop;

  update equipment_requests
    set status = p_status, fulfillment_note = p_note
    where id = p_request_id;
end;
$$;

create or replace function release_equipment_for_event(p_event_id integer)
returns void
language plpgsql
as $$
declare
  item record;
begin
  for item in
    select eri.id, eri.quantity_fulfilled, eri.equipment_catalog_id
    from equipment_request_items eri
    join equipment_requests er on er.id = eri.request_id
    where er.event_id = p_event_id and eri.quantity_fulfilled > 0
    order by eri.equipment_catalog_id, eri.id
  loop
    update equipment_request_items
      set quantity_fulfilled = 0
      where id = item.id;
  end loop;

  delete from equipment_booking where event_id = p_event_id;
end;
$$;

create or replace function amend_equipment_request(p_request_id bigint, p_items jsonb)
returns jsonb
language plpgsql
as $$
declare
  req_status text;
  item record;
  spec jsonb;
  new_qty integer;
  new_catalog bigint;
  new_type text;
  surplus integer;
  total_fulfilled integer;
  all_met boolean;
  new_status text;
  changes jsonb := '[]'::jsonb;
begin
  select status into req_status from equipment_requests where id = p_request_id for update;
  if not found then
    raise exception 'Equipment request not found: %', p_request_id;
  end if;
  if req_status not in ('Requested', 'Partially Fulfilled') then
    raise exception 'Equipment request cannot be amended: %', req_status;
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'At least one item is required';
  end if;

  if exists (
    select 1 from jsonb_array_elements(p_items) as e(v)
    where e.v->>'itemId' is not null
      and not exists (
        select 1 from equipment_request_items i
        where i.id = (e.v->>'itemId')::bigint and i.request_id = p_request_id
      )
  ) then
    raise exception 'Unknown item in amendment';
  end if;

  for item in
    select id, equipment_type, quantity, quantity_fulfilled, equipment_catalog_id
    from equipment_request_items
    where request_id = p_request_id
    order by equipment_catalog_id, id
  loop
    select e.v into spec
    from jsonb_array_elements(p_items) as e(v)
    where (e.v->>'itemId')::bigint = item.id
    limit 1;

    if spec is null then
      -- Removed: give back everything it held. Its equipment_booking rows go
      -- with it (on delete cascade, migration 0027).
      delete from equipment_request_items where id = item.id;
      changes := changes || jsonb_build_object(
        'kind', 'removed',
        'equipmentType', item.equipment_type,
        'quantity', item.quantity,
        'released', item.quantity_fulfilled
      );
      continue;
    end if;

    new_qty := (spec->>'quantity')::integer;
    new_catalog := (spec->>'equipmentCatalogId')::bigint;
    new_type := spec->>'equipmentType';

    if new_catalog is distinct from item.equipment_catalog_id then
      delete from equipment_booking where request_item_id = item.id;
      update equipment_request_items
        set equipment_catalog_id = new_catalog,
            equipment_type = new_type,
            quantity = new_qty,
            quantity_fulfilled = 0
        where id = item.id;
      changes := changes || jsonb_build_object(
        'kind', 'type',
        'fromType', item.equipment_type,
        'equipmentType', new_type,
        'from', item.quantity,
        'to', new_qty,
        'released', item.quantity_fulfilled
      );
    elsif new_qty <> item.quantity then
      surplus := greatest(0, item.quantity_fulfilled - new_qty);
      if surplus > 0 then
        delete from equipment_booking
          where id in (
            select id from equipment_booking
            where request_item_id = item.id
            order by id
            limit surplus
          );
      end if;
      update equipment_request_items
        set quantity = new_qty,
            quantity_fulfilled = least(item.quantity_fulfilled, new_qty)
        where id = item.id;
      changes := changes || jsonb_build_object(
        'kind', 'quantity',
        'equipmentType', item.equipment_type,
        'from', item.quantity,
        'to', new_qty,
        'released', surplus
      );
    end if;
  end loop;

  for spec in
    select e.v from jsonb_array_elements(p_items) as e(v) where e.v->>'itemId' is null
  loop
    insert into equipment_request_items (request_id, equipment_catalog_id, equipment_type, quantity)
    values (
      p_request_id,
      (spec->>'equipmentCatalogId')::bigint,
      spec->>'equipmentType',
      (spec->>'quantity')::integer
    );
    changes := changes || jsonb_build_object(
      'kind', 'added',
      'equipmentType', spec->>'equipmentType',
      'quantity', (spec->>'quantity')::integer,
      'released', 0
    );
  end loop;

  select coalesce(sum(quantity_fulfilled), 0), coalesce(bool_and(quantity_fulfilled >= quantity), false)
    into total_fulfilled, all_met
    from equipment_request_items
    where request_id = p_request_id;

  if total_fulfilled = 0 then
    new_status := 'Requested';
  elsif all_met then
    new_status := 'Arranged';
  else
    new_status := 'Partially Fulfilled';
  end if;

  update equipment_requests
    set status = new_status,
        fulfillment_note = case when new_status = 'Partially Fulfilled' then fulfillment_note else null end
    where id = p_request_id;

  return jsonb_build_object('status', new_status, 'changes', changes);
end;
$$;

create or replace function release_equipment_for_request(p_request_id bigint)
returns jsonb
language plpgsql
as $$
declare
  req_status text;
  item record;
  released jsonb := '[]'::jsonb;
begin
  select status into req_status from equipment_requests where id = p_request_id for update;
  if not found then
    raise exception 'Equipment request not found: %', p_request_id;
  end if;
  if req_status = 'Cancelled' then
    raise exception 'Equipment request already cancelled: %', p_request_id;
  end if;

  for item in
    select id, equipment_type, quantity_fulfilled, equipment_catalog_id
    from equipment_request_items
    where request_id = p_request_id
    order by equipment_catalog_id, id
  loop
    if item.quantity_fulfilled > 0 then
      released := released || jsonb_build_object(
        'equipmentType', item.equipment_type,
        'quantity', item.quantity_fulfilled
      );
      update equipment_request_items set quantity_fulfilled = 0 where id = item.id;
    end if;
    delete from equipment_booking where request_item_id = item.id;
  end loop;

  update equipment_requests
    set status = 'Cancelled', fulfillment_note = null
    where id = p_request_id;

  return jsonb_build_object('released', released);
end;
$$;

create or replace function change_equipment_stock(
  p_catalog_id bigint,
  p_delta integer,
  p_reason text,
  p_user text
)
returns jsonb
language plpgsql
as $$
declare
  cat record;
  free_ids bigint[];
  removable integer;
  wanted integer;
  total_before integer;
  total_after integer;
begin
  if p_delta is null or p_delta = 0 then
    raise exception 'Quantity must be at least 1';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'A reason is required';
  end if;

  select id, name into cat from equipment_catalog where id = p_catalog_id for update;
  if not found then
    raise exception 'Equipment item not found: %', p_catalog_id;
  end if;

  select count(*) into total_before from equipment where equipment_catalog_id = cat.id;

  if p_delta > 0 then
    insert into equipment (type, status, equipment_catalog_id)
      select cat.name, 'Available', cat.id from generate_series(1, p_delta);
  else
    wanted := -p_delta;
    select coalesce(array_agg(s.id), '{}') into free_ids from (
      select e.id
      from equipment e
      where e.equipment_catalog_id = cat.id
        and e.status = 'Available'
        and not exists (select 1 from equipment_booking b where b.equipment_id = e.id)
        and not exists (
          select 1 from equipment_unavailability u
          where u.equipment_id = e.id and (u.end_date is null or u.end_date >= current_date)
        )
      order by e.id desc
      limit wanted
    ) s;

    removable := coalesce(array_length(free_ids, 1), 0);
    if removable < wanted then
      raise exception 'Cannot remove %: only % can be removed', wanted, removable;
    end if;

    delete from equipment where id = any(free_ids);
  end if;

  total_after := total_before + p_delta;

  insert into equipment_stock_changes
    (equipment_catalog_id, change_type, quantity, total_before, total_after, reason, changed_by)
  values
    (cat.id, case when p_delta > 0 then 'Added' else 'Removed' end, abs(p_delta),
     total_before, total_after, btrim(p_reason), p_user);

  return jsonb_build_object('id', cat.id, 'name', cat.name, 'totalStock', total_after);
end;
$$;

create or replace function catalog_stock_now(p_day date, p_start_ms bigint, p_end_ms bigint)
returns table (catalog_id bigint, total integer, unusable_now integer, available integer)
language sql
stable
as $$
  with unit as (
    select
      e.equipment_catalog_id as catalog_id,
      (
        e.status <> 'Available'
        or exists (
          select 1 from equipment_unavailability u
          where u.equipment_id = e.id
            and u.start_date <= p_day
            and (u.end_date is null or u.end_date >= p_day)
        )
      ) as unusable,
      exists (
        select 1 from equipment_booking b
        where b.equipment_id = e.id
          and b.window_start_ms is not null
          and b.window_start_ms < p_end_ms
          and p_start_ms < b.window_end_ms
      ) as booked
    from equipment e
  )
  select
    c.id,
    count(u.catalog_id)::integer,
    count(*) filter (where u.unusable)::integer,
    count(*) filter (where not u.unusable and not u.booked)::integer
  from equipment_catalog c
  left join unit u on u.catalog_id = c.id
  group by c.id;
$$;

create or replace function reserve_equipment_request(
  p_request_id bigint,
  p_status text,
  p_note text,
  p_fulfillments jsonb default '[]'::jsonb,
  p_claims jsonb default '[]'::jsonb,
  p_window_start_ms bigint default null,
  p_window_end_ms bigint default null
)
returns void
language plpgsql
as $$
declare
  req record;
  before_fulfilled jsonb;
  item record;
  claim jsonb;
  claimed bigint[];
  delta integer;
  unit record;
  found_units integer;
  first_day date;
  last_day date;
begin
  select id, event_id into req from equipment_requests where id = p_request_id for update;
  if not found then
    raise exception 'Equipment request not found: %', p_request_id;
  end if;

  -- What each item held before, to tell how many units to claim or release.
  select coalesce(jsonb_object_agg(id::text, quantity_fulfilled), '{}'::jsonb)
    into before_fulfilled
    from equipment_request_items
    where request_id = p_request_id;

  -- The stock counters and the request status (0022). Raises if there is not enough stock.
  perform apply_equipment_request_status(p_request_id, p_status, p_note, p_fulfillments);

  for item in
    select id, equipment_catalog_id, quantity_fulfilled
    from equipment_request_items
    where request_id = p_request_id
    order by id
  loop
    delta := item.quantity_fulfilled - coalesce((before_fulfilled ->> item.id::text)::integer, 0);

    if delta < 0 then
      delete from equipment_booking
      where id in (
        select id from equipment_booking where request_item_id = item.id order by id limit -delta
      );

    elsif delta > 0 then
      select e.c into claim
        from jsonb_array_elements(p_claims) as e(c)
        where (e.c ->> 'itemId')::bigint = item.id
        limit 1;
      if claim is null then
        raise exception 'No units were chosen for item %', item.id;
      end if;

      if p_window_start_ms is null or p_window_end_ms is null or p_window_end_ms <= p_window_start_ms then
        raise exception 'The event window is required to reserve item %', item.id;
      end if;
      -- Whole days the window touches, for comparing with unavailability periods
      -- (end is exclusive, so the last day is the one holding end - 1 ms).
      first_day := (to_timestamp(p_window_start_ms / 1000.0) at time zone 'UTC')::date;
      last_day := (to_timestamp((p_window_end_ms - 1) / 1000.0) at time zone 'UTC')::date;

      select coalesce(array_agg(t.value::bigint), '{}') into claimed
        from jsonb_array_elements_text(claim -> 'unitIds') as t(value);
      if (select count(distinct x) from unnest(claimed) as x) <> delta
         or coalesce(array_length(claimed, 1), 0) <> delta then
        raise exception 'Item % needs % units but % were chosen', item.id, delta, coalesce(array_length(claimed, 1), 0);
      end if;

      -- Lock the units so two reservations of the same unit run one after the other.
      found_units := 0;
      for unit in
        select id, equipment_catalog_id, status
        from equipment
        where id = any(claimed)
        order by id
        for update
      loop
        found_units := found_units + 1;
        if unit.equipment_catalog_id is distinct from item.equipment_catalog_id then
          raise exception 'Unit % is not the requested equipment type', unit.id;
        end if;
        if unit.status <> 'Available' then
          raise exception 'Unit % is no longer available', unit.id;
        end if;
        if exists (
          select 1 from equipment_booking b where b.equipment_id = unit.id and b.event_id = req.event_id
        ) then
          raise exception 'Unit % is already reserved for this event', unit.id;
        end if;
        if exists (
          select 1 from equipment_booking b
          where b.equipment_id = unit.id
            and b.window_start_ms is not null
            and b.window_start_ms < p_window_end_ms
            and p_window_start_ms < b.window_end_ms
        ) then
          raise exception 'Unit % is already booked for overlapping dates', unit.id;
        end if;
        if exists (
          select 1 from equipment_unavailability u
          where u.equipment_id = unit.id
            and u.start_date <= last_day
            and (u.end_date is null or u.end_date >= first_day)
        ) then
          raise exception 'Unit % is unavailable during these dates', unit.id;
        end if;
      end loop;
      if found_units <> delta then
        raise exception 'Unknown equipment unit in the claim for item %', item.id;
      end if;

      insert into equipment_booking (equipment_id, event_id, request_item_id, window_start_ms, window_end_ms)
        select u, req.event_id, item.id, p_window_start_ms, p_window_end_ms from unnest(claimed) as u;
    end if;
  end loop;
end;
$$;

-- ===== 0052_equipment_booking_history.sql =====
-- Keep a history of equipment reservations: a released booking is marked, not deleted.
--
-- equipment_booking rows were deleted whenever equipment was released (event or
-- request cancelled, request reverted, quantity lowered, item removed or
-- retyped), so nothing recorded which units an event had held. Now:
--   status          enum equipment_booking_status: 'Reserved' (holds the unit) or
--                   'Released' (freed, kept for audit);
--   released_at     when it was freed;
--   release_reason  why: Event cancelled, Request cancelled, Fulfilment reduced,
--                   Quantity lowered, Item removed, Item type changed.
-- Only 'Reserved' rows count as booked: the overlap check, "already reserved for
-- this event", the catalog's available-today count and the check on which units
-- stock removal may take all ignore 'Released' rows.
--
-- The two foreign keys no longer delete history. request_item_id (0027) was
-- "on delete cascade", so removing a request item removed its bookings; it is
-- now "on delete set null". equipment_id had no cascade, so deleting a unit
-- (stock removal) failed once it had any booking; it is now "on delete set null"
-- too, which means a removed unit's old rows keep the event, dates and reason but
-- lose the unit id. Stock removal still only takes units with no Reserved booking.
--
-- Existing rows become 'Reserved'. Guarded so this is safe to re-run.

-- status is a Postgres enum like every other status column (AGENTS.md section 5), so
-- the database rejects any other value. If a text column was created by an earlier
-- run of this migration, it is converted in place.
do $$
begin
  if not exists (select 1 from pg_type where typname = 'equipment_booking_status') then
    create type equipment_booking_status as enum ('Reserved', 'Released');
  end if;

  if not exists (
    select 1 from information_schema.columns
    where table_name = 'equipment_booking' and column_name = 'status'
  ) then
    alter table equipment_booking add column status equipment_booking_status not null default 'Reserved';
  elsif (
    select data_type from information_schema.columns
    where table_name = 'equipment_booking' and column_name = 'status'
  ) = 'text' then
    alter table equipment_booking drop constraint if exists equipment_booking_status_check;
    alter table equipment_booking drop constraint if exists equipment_booking_released_check;
    alter table equipment_booking alter column status drop default;
    alter table equipment_booking
      alter column status type equipment_booking_status using status::equipment_booking_status;
    alter table equipment_booking alter column status set default 'Reserved';
  end if;
end
$$;

alter table equipment_booking add column if not exists released_at timestamptz;
alter table equipment_booking add column if not exists release_reason text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'equipment_booking_released_check') then
    alter table equipment_booking
      add constraint equipment_booking_released_check
      check ((status = 'Released') = (released_at is not null));
  end if;
end
$$;

alter table equipment_booking drop constraint if exists equipment_booking_request_item_id_fkey;
alter table equipment_booking
  add constraint equipment_booking_request_item_id_fkey
  foreign key (request_item_id) references equipment_request_items (id) on delete set null;

alter table equipment_booking drop constraint if exists equipment_booking_equipment_id_fkey;
alter table equipment_booking
  add constraint equipment_booking_equipment_id_fkey
  foreign key (equipment_id) references equipment (id) on delete set null;

create index if not exists equipment_booking_status_idx on equipment_booking (equipment_id, status);

create or replace function release_equipment_for_event(p_event_id integer)
returns void
language plpgsql
as $$
declare
  item record;
begin
  for item in
    select eri.id, eri.quantity_fulfilled, eri.equipment_catalog_id
    from equipment_request_items eri
    join equipment_requests er on er.id = eri.request_id
    where er.event_id = p_event_id and eri.quantity_fulfilled > 0
    order by eri.equipment_catalog_id, eri.id
  loop
    update equipment_request_items
      set quantity_fulfilled = 0
      where id = item.id;
  end loop;

  update equipment_booking set status = 'Released', released_at = now(), release_reason = 'Event cancelled'
    where event_id = p_event_id and status = 'Reserved';
end;
$$;

create or replace function amend_equipment_request(p_request_id bigint, p_items jsonb)
returns jsonb
language plpgsql
as $$
declare
  req_status text;
  item record;
  spec jsonb;
  new_qty integer;
  new_catalog bigint;
  new_type text;
  surplus integer;
  total_fulfilled integer;
  all_met boolean;
  new_status text;
  changes jsonb := '[]'::jsonb;
begin
  select status into req_status from equipment_requests where id = p_request_id for update;
  if not found then
    raise exception 'Equipment request not found: %', p_request_id;
  end if;
  if req_status not in ('Requested', 'Partially Fulfilled') then
    raise exception 'Equipment request cannot be amended: %', req_status;
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'At least one item is required';
  end if;

  if exists (
    select 1 from jsonb_array_elements(p_items) as e(v)
    where e.v->>'itemId' is not null
      and not exists (
        select 1 from equipment_request_items i
        where i.id = (e.v->>'itemId')::bigint and i.request_id = p_request_id
      )
  ) then
    raise exception 'Unknown item in amendment';
  end if;

  for item in
    select id, equipment_type, quantity, quantity_fulfilled, equipment_catalog_id
    from equipment_request_items
    where request_id = p_request_id
    order by equipment_catalog_id, id
  loop
    select e.v into spec
    from jsonb_array_elements(p_items) as e(v)
    where (e.v->>'itemId')::bigint = item.id
    limit 1;

    if spec is null then
      -- Removed: give back everything it held. Its bookings are marked Released
      -- and stay as history (their request_item_id is cleared by the delete).
      update equipment_booking set status = 'Released', released_at = now(), release_reason = 'Item removed'
        where request_item_id = item.id and status = 'Reserved';
      delete from equipment_request_items where id = item.id;
      changes := changes || jsonb_build_object(
        'kind', 'removed',
        'equipmentType', item.equipment_type,
        'quantity', item.quantity,
        'released', item.quantity_fulfilled
      );
      continue;
    end if;

    new_qty := (spec->>'quantity')::integer;
    new_catalog := (spec->>'equipmentCatalogId')::bigint;
    new_type := spec->>'equipmentType';

    if new_catalog is distinct from item.equipment_catalog_id then
      update equipment_booking set status = 'Released', released_at = now(), release_reason = 'Item type changed'
        where request_item_id = item.id and status = 'Reserved';
      update equipment_request_items
        set equipment_catalog_id = new_catalog,
            equipment_type = new_type,
            quantity = new_qty,
            quantity_fulfilled = 0
        where id = item.id;
      changes := changes || jsonb_build_object(
        'kind', 'type',
        'fromType', item.equipment_type,
        'equipmentType', new_type,
        'from', item.quantity,
        'to', new_qty,
        'released', item.quantity_fulfilled
      );
    elsif new_qty <> item.quantity then
      surplus := greatest(0, item.quantity_fulfilled - new_qty);
      if surplus > 0 then
        update equipment_booking set status = 'Released', released_at = now(), release_reason = 'Quantity lowered'
          where id in (
            select id from equipment_booking
            where request_item_id = item.id and status = 'Reserved'
            order by id
            limit surplus
          );
      end if;
      update equipment_request_items
        set quantity = new_qty,
            quantity_fulfilled = least(item.quantity_fulfilled, new_qty)
        where id = item.id;
      changes := changes || jsonb_build_object(
        'kind', 'quantity',
        'equipmentType', item.equipment_type,
        'from', item.quantity,
        'to', new_qty,
        'released', surplus
      );
    end if;
  end loop;

  for spec in
    select e.v from jsonb_array_elements(p_items) as e(v) where e.v->>'itemId' is null
  loop
    insert into equipment_request_items (request_id, equipment_catalog_id, equipment_type, quantity)
    values (
      p_request_id,
      (spec->>'equipmentCatalogId')::bigint,
      spec->>'equipmentType',
      (spec->>'quantity')::integer
    );
    changes := changes || jsonb_build_object(
      'kind', 'added',
      'equipmentType', spec->>'equipmentType',
      'quantity', (spec->>'quantity')::integer,
      'released', 0
    );
  end loop;

  select coalesce(sum(quantity_fulfilled), 0), coalesce(bool_and(quantity_fulfilled >= quantity), false)
    into total_fulfilled, all_met
    from equipment_request_items
    where request_id = p_request_id;

  if total_fulfilled = 0 then
    new_status := 'Requested';
  elsif all_met then
    new_status := 'Arranged';
  else
    new_status := 'Partially Fulfilled';
  end if;

  update equipment_requests
    set status = new_status,
        fulfillment_note = case when new_status = 'Partially Fulfilled' then fulfillment_note else null end
    where id = p_request_id;

  return jsonb_build_object('status', new_status, 'changes', changes);
end;
$$;

create or replace function release_equipment_for_request(p_request_id bigint)
returns jsonb
language plpgsql
as $$
declare
  req_status text;
  item record;
  released jsonb := '[]'::jsonb;
begin
  select status into req_status from equipment_requests where id = p_request_id for update;
  if not found then
    raise exception 'Equipment request not found: %', p_request_id;
  end if;
  if req_status = 'Cancelled' then
    raise exception 'Equipment request already cancelled: %', p_request_id;
  end if;

  for item in
    select id, equipment_type, quantity_fulfilled, equipment_catalog_id
    from equipment_request_items
    where request_id = p_request_id
    order by equipment_catalog_id, id
  loop
    if item.quantity_fulfilled > 0 then
      released := released || jsonb_build_object(
        'equipmentType', item.equipment_type,
        'quantity', item.quantity_fulfilled
      );
      update equipment_request_items set quantity_fulfilled = 0 where id = item.id;
    end if;
    update equipment_booking set status = 'Released', released_at = now(), release_reason = 'Request cancelled'
      where request_item_id = item.id and status = 'Reserved';
  end loop;

  update equipment_requests
    set status = 'Cancelled', fulfillment_note = null
    where id = p_request_id;

  return jsonb_build_object('released', released);
end;
$$;

create or replace function change_equipment_stock(
  p_catalog_id bigint,
  p_delta integer,
  p_reason text,
  p_user text
)
returns jsonb
language plpgsql
as $$
declare
  cat record;
  free_ids bigint[];
  removable integer;
  wanted integer;
  total_before integer;
  total_after integer;
begin
  if p_delta is null or p_delta = 0 then
    raise exception 'Quantity must be at least 1';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'A reason is required';
  end if;

  select id, name into cat from equipment_catalog where id = p_catalog_id for update;
  if not found then
    raise exception 'Equipment item not found: %', p_catalog_id;
  end if;

  select count(*) into total_before from equipment where equipment_catalog_id = cat.id;

  if p_delta > 0 then
    insert into equipment (type, status, equipment_catalog_id)
      select cat.name, 'Available', cat.id from generate_series(1, p_delta);
  else
    wanted := -p_delta;
    select coalesce(array_agg(s.id), '{}') into free_ids from (
      select e.id
      from equipment e
      where e.equipment_catalog_id = cat.id
        and e.status = 'Available'
        and not exists (select 1 from equipment_booking b where b.equipment_id = e.id and b.status = 'Reserved')
        and not exists (
          select 1 from equipment_unavailability u
          where u.equipment_id = e.id and (u.end_date is null or u.end_date >= current_date)
        )
      order by e.id desc
      limit wanted
    ) s;

    removable := coalesce(array_length(free_ids, 1), 0);
    if removable < wanted then
      raise exception 'Cannot remove %: only % can be removed', wanted, removable;
    end if;

    delete from equipment where id = any(free_ids);
  end if;

  total_after := total_before + p_delta;

  insert into equipment_stock_changes
    (equipment_catalog_id, change_type, quantity, total_before, total_after, reason, changed_by)
  values
    (cat.id, case when p_delta > 0 then 'Added' else 'Removed' end, abs(p_delta),
     total_before, total_after, btrim(p_reason), p_user);

  return jsonb_build_object('id', cat.id, 'name', cat.name, 'totalStock', total_after);
end;
$$;

create or replace function catalog_stock_now(p_day date, p_start_ms bigint, p_end_ms bigint)
returns table (catalog_id bigint, total integer, unusable_now integer, available integer)
language sql
stable
as $$
  with unit as (
    select
      e.equipment_catalog_id as catalog_id,
      (
        e.status <> 'Available'
        or exists (
          select 1 from equipment_unavailability u
          where u.equipment_id = e.id
            and u.start_date <= p_day
            and (u.end_date is null or u.end_date >= p_day)
        )
      ) as unusable,
      exists (
        select 1 from equipment_booking b
        where b.equipment_id = e.id
          and b.status = 'Reserved'
          and b.window_start_ms is not null
          and b.window_start_ms < p_end_ms
          and p_start_ms < b.window_end_ms
      ) as booked
    from equipment e
  )
  select
    c.id,
    count(u.catalog_id)::integer,
    count(*) filter (where u.unusable)::integer,
    count(*) filter (where not u.unusable and not u.booked)::integer
  from equipment_catalog c
  left join unit u on u.catalog_id = c.id
  group by c.id;
$$;

create or replace function reserve_equipment_request(
  p_request_id bigint,
  p_status text,
  p_note text,
  p_fulfillments jsonb default '[]'::jsonb,
  p_claims jsonb default '[]'::jsonb,
  p_window_start_ms bigint default null,
  p_window_end_ms bigint default null
)
returns void
language plpgsql
as $$
declare
  req record;
  before_fulfilled jsonb;
  item record;
  claim jsonb;
  claimed bigint[];
  delta integer;
  unit record;
  found_units integer;
  first_day date;
  last_day date;
begin
  select id, event_id into req from equipment_requests where id = p_request_id for update;
  if not found then
    raise exception 'Equipment request not found: %', p_request_id;
  end if;

  -- What each item held before, to tell how many units to claim or release.
  select coalesce(jsonb_object_agg(id::text, quantity_fulfilled), '{}'::jsonb)
    into before_fulfilled
    from equipment_request_items
    where request_id = p_request_id;

  -- The stock counters and the request status (0022). Raises if there is not enough stock.
  perform apply_equipment_request_status(p_request_id, p_status, p_note, p_fulfillments);

  for item in
    select id, equipment_catalog_id, quantity_fulfilled
    from equipment_request_items
    where request_id = p_request_id
    order by id
  loop
    delta := item.quantity_fulfilled - coalesce((before_fulfilled ->> item.id::text)::integer, 0);

    if delta < 0 then
      update equipment_booking set status = 'Released', released_at = now(), release_reason = 'Fulfilment reduced'
      where id in (
        select id from equipment_booking
        where request_item_id = item.id and status = 'Reserved'
        order by id
        limit -delta
      );

    elsif delta > 0 then
      select e.c into claim
        from jsonb_array_elements(p_claims) as e(c)
        where (e.c ->> 'itemId')::bigint = item.id
        limit 1;
      if claim is null then
        raise exception 'No units were chosen for item %', item.id;
      end if;

      if p_window_start_ms is null or p_window_end_ms is null or p_window_end_ms <= p_window_start_ms then
        raise exception 'The event window is required to reserve item %', item.id;
      end if;
      -- Whole days the window touches, for comparing with unavailability periods
      -- (end is exclusive, so the last day is the one holding end - 1 ms).
      first_day := (to_timestamp(p_window_start_ms / 1000.0) at time zone 'UTC')::date;
      last_day := (to_timestamp((p_window_end_ms - 1) / 1000.0) at time zone 'UTC')::date;

      select coalesce(array_agg(t.value::bigint), '{}') into claimed
        from jsonb_array_elements_text(claim -> 'unitIds') as t(value);
      if (select count(distinct x) from unnest(claimed) as x) <> delta
         or coalesce(array_length(claimed, 1), 0) <> delta then
        raise exception 'Item % needs % units but % were chosen', item.id, delta, coalesce(array_length(claimed, 1), 0);
      end if;

      -- Lock the units so two reservations of the same unit run one after the other.
      found_units := 0;
      for unit in
        select id, equipment_catalog_id, status
        from equipment
        where id = any(claimed)
        order by id
        for update
      loop
        found_units := found_units + 1;
        if unit.equipment_catalog_id is distinct from item.equipment_catalog_id then
          raise exception 'Unit % is not the requested equipment type', unit.id;
        end if;
        if unit.status <> 'Available' then
          raise exception 'Unit % is no longer available', unit.id;
        end if;
        if exists (
          select 1 from equipment_booking b
          where b.equipment_id = unit.id and b.event_id = req.event_id and b.status = 'Reserved'
        ) then
          raise exception 'Unit % is already reserved for this event', unit.id;
        end if;
        if exists (
          select 1 from equipment_booking b
          where b.equipment_id = unit.id
            and b.status = 'Reserved'
            and b.window_start_ms is not null
            and b.window_start_ms < p_window_end_ms
            and p_window_start_ms < b.window_end_ms
        ) then
          raise exception 'Unit % is already booked for overlapping dates', unit.id;
        end if;
        if exists (
          select 1 from equipment_unavailability u
          where u.equipment_id = unit.id
            and u.start_date <= last_day
            and (u.end_date is null or u.end_date >= first_day)
        ) then
          raise exception 'Unit % is unavailable during these dates', unit.id;
        end if;
      end loop;
      if found_units <> delta then
        raise exception 'Unknown equipment unit in the claim for item %', item.id;
      end if;

      insert into equipment_booking (equipment_id, event_id, request_item_id, window_start_ms, window_end_ms)
        select u, req.event_id, item.id, p_window_start_ms, p_window_end_ms from unnest(claimed) as u;
    end if;
  end loop;
end;
$$;

-- ===== 0053_catalog_total_stock_trigger.sql =====
-- Drop the stored available_stock counter; keep total_stock, but have the
-- database keep it equal to the number of unit rows.
--
-- available_stock was a date-blind running total that 0051 stopped using. What
-- is "available" depends on the date (bookings, unusable periods), so it is
-- worked out when read (catalog_stock_now, 0051) and has no place as a column.
--
-- total_stock stays because it is a plain fact that only changes when a unit
-- row is added or removed. Instead of the application remembering to update it
-- (change_equipment_stock and the catalog POST used to, then stopped in 0051),
-- a trigger on `equipment` recomputes it for the catalog items touched by any
-- insert, delete or update, so it cannot drift. Statement-level, so adding
-- 1000 units recounts once, not 1000 times.
--
-- This also means total_stock can no longer be used as an input: seeds that
-- built units from it now carry the quantities themselves (seed.sql,
-- scripts/seed_equipment.sql). Writing total_stock by hand is overwritten the
-- next time a unit changes.
--
-- Guarded so this is safe to re-run.

alter table equipment_catalog drop column if exists available_stock;

create or replace function sync_catalog_total_stock()
returns trigger
language plpgsql
as $$
begin
  if tg_op in ('INSERT', 'UPDATE') then
    update equipment_catalog c
      set total_stock = (select count(*) from equipment e where e.equipment_catalog_id = c.id)
      where c.id in (select equipment_catalog_id from new_rows where equipment_catalog_id is not null);
  end if;
  if tg_op in ('DELETE', 'UPDATE') then
    update equipment_catalog c
      set total_stock = (select count(*) from equipment e where e.equipment_catalog_id = c.id)
      where c.id in (select equipment_catalog_id from old_rows where equipment_catalog_id is not null);
  end if;
  return null;
end;
$$;

drop trigger if exists equipment_total_stock_insert on equipment;
create trigger equipment_total_stock_insert
  after insert on equipment
  referencing new table as new_rows
  for each statement execute function sync_catalog_total_stock();

drop trigger if exists equipment_total_stock_update on equipment;
create trigger equipment_total_stock_update
  after update on equipment
  referencing old table as old_rows new table as new_rows
  for each statement execute function sync_catalog_total_stock();

drop trigger if exists equipment_total_stock_delete on equipment;
create trigger equipment_total_stock_delete
  after delete on equipment
  referencing old table as old_rows
  for each statement execute function sync_catalog_total_stock();

-- Catch up anything that drifted while nothing maintained the column.
update equipment_catalog c
  set total_stock = (select count(*) from equipment e where e.equipment_catalog_id = c.id);



-- ===== 0054_fulfilled_quantity_trigger.sql =====
-- Keep equipment_request_items.quantity_fulfilled equal to the number of
-- Reserved bookings for the item, by trigger.
--
-- quantity_fulfilled is the request's record of how many units it holds. The
-- units themselves are the Reserved rows in equipment_booking, so the two must
-- always agree. Until now every function that touched a booking also updated
-- the counter by hand, so a new code path (or a manual fix in SQL) that forgot
-- would let them drift. A statement-level trigger on equipment_booking now
-- recomputes the count for each item a statement touched, the same approach as
-- total_stock (0053). The existing functions still write the column; they now
-- write the value the trigger would, so nothing about them has to change.
--
-- Guarded so this is safe to re-run.

create or replace function sync_item_quantity_fulfilled()
returns trigger
language plpgsql
as $$
begin
  if tg_op in ('INSERT', 'UPDATE') then
    update equipment_request_items i
      set quantity_fulfilled = (
        select count(*) from equipment_booking b
        where b.request_item_id = i.id and b.status = 'Reserved'
      )
      where i.id in (select request_item_id from new_rows where request_item_id is not null);
  end if;
  if tg_op in ('DELETE', 'UPDATE') then
    update equipment_request_items i
      set quantity_fulfilled = (
        select count(*) from equipment_booking b
        where b.request_item_id = i.id and b.status = 'Reserved'
      )
      where i.id in (select request_item_id from old_rows where request_item_id is not null);
  end if;
  return null;
end;
$$;

drop trigger if exists equipment_booking_fulfilled_insert on equipment_booking;
create trigger equipment_booking_fulfilled_insert
  after insert on equipment_booking
  referencing new table as new_rows
  for each statement execute function sync_item_quantity_fulfilled();

drop trigger if exists equipment_booking_fulfilled_update on equipment_booking;
create trigger equipment_booking_fulfilled_update
  after update on equipment_booking
  referencing old table as old_rows new table as new_rows
  for each statement execute function sync_item_quantity_fulfilled();

drop trigger if exists equipment_booking_fulfilled_delete on equipment_booking;
create trigger equipment_booking_fulfilled_delete
  after delete on equipment_booking
  referencing old table as old_rows
  for each statement execute function sync_item_quantity_fulfilled();

-- Catch up anything that drifted before the trigger existed.
update equipment_request_items i
  set quantity_fulfilled = (
    select count(*) from equipment_booking b
    where b.request_item_id = i.id and b.status = 'Reserved'
  )
  where quantity_fulfilled <> (
    select count(*) from equipment_booking b
    where b.request_item_id = i.id and b.status = 'Reserved'
  );


-- ===== 0055_equipment_reschedule_clashes.sql =====
-- Which of an event's reserved units now clash, after the event was rescheduled.
--
-- When an event moves, equipment-service rewrites the stored window on its
-- Reserved bookings (event.rescheduled). That is a plain update, and the
-- overlap checks in reserve_equipment_request only run when units are reserved,
-- so nothing noticed that the new window may overlap another event's booking
-- of the same unit, or a period the unit is out of use. This lists those, so
-- equipment-service can notify the coordinator and Technical Support (and have
-- a Confirmed event moved to Needs Review).
--
-- One row per clashing booking of the event:
--   item_id  the request item the booking belongs to
--   unit_id  the unit
--   kind     'booking'      another event's Reserved booking overlaps the window
--            'unavailable'  a period the unit is out of use (E5-5) touches the
--                           window's days
-- A booking with no stored window (made before 0050) can't be compared and is
-- left out. The unavailability test is the one reserve_equipment_request uses:
-- whole days, the last day being the one holding the window's end minus 1 ms.
--
-- Read-only and stable. Guarded (create or replace) so it is safe to re-run.

create or replace function equipment_reschedule_clashes(p_event_id bigint)
returns table (item_id bigint, unit_id bigint, kind text)
language sql
stable
as $$
  select b.request_item_id, b.equipment_id, 'booking'::text
  from equipment_booking b
  where b.event_id = p_event_id
    and b.status = 'Reserved'
    and b.window_start_ms is not null
    and b.window_end_ms is not null
    and exists (
      select 1 from equipment_booking o
      where o.equipment_id = b.equipment_id
        and o.event_id <> b.event_id
        and o.status = 'Reserved'
        and o.window_start_ms is not null
        and o.window_start_ms < b.window_end_ms
        and b.window_start_ms < o.window_end_ms
    )
  union all
  select b.request_item_id, b.equipment_id, 'unavailable'::text
  from equipment_booking b
  where b.event_id = p_event_id
    and b.status = 'Reserved'
    and b.window_start_ms is not null
    and b.window_end_ms is not null
    and exists (
      select 1 from equipment_unavailability u
      where u.equipment_id = b.equipment_id
        and u.start_date <= (to_timestamp((b.window_end_ms - 1) / 1000.0) at time zone 'UTC')::date
        and (u.end_date is null or u.end_date >= (to_timestamp(b.window_start_ms / 1000.0) at time zone 'UTC')::date)
    );
$$;


-- ===== 0056_cancel_requests_with_event.sql =====
-- When an event is cancelled, its equipment requests are cancelled too.
--
-- release_equipment_for_event (E3-6, run when equipment-service receives
-- event.cancelled) freed the event's units and zeroed each item's
-- quantity_fulfilled, but left the request's status alone. Technical Support
-- then still saw the cancelled event's request in their queue, as "Arranged"
-- or "Partially Fulfilled" with every item "Not arranged", or as "Requested" and
-- waiting for them to act on it.
--
-- It now also sets every request of the event that is not already Cancelled to
-- 'Cancelled' and clears its outstanding note. A Cancelled request is already
-- out of Technical Support's queue (E5-2) and shows greyed out to the
-- coordinator, with its items kept as history. The bookings are released as
-- before, with the reason 'Event cancelled' (0052).
--
-- Safe to run twice: a second run finds nothing left to cancel or release.
-- Guarded (create or replace) so this is safe to re-run.

create or replace function release_equipment_for_event(p_event_id integer)
returns void
language plpgsql
as $$
declare
  item record;
begin
  for item in
    select eri.id, eri.quantity_fulfilled, eri.equipment_catalog_id
    from equipment_request_items eri
    join equipment_requests er on er.id = eri.request_id
    where er.event_id = p_event_id and eri.quantity_fulfilled > 0
    order by eri.equipment_catalog_id, eri.id
  loop
    update equipment_request_items
      set quantity_fulfilled = 0
      where id = item.id;
  end loop;

  update equipment_booking set status = 'Released', released_at = now(), release_reason = 'Event cancelled'
    where event_id = p_event_id and status = 'Reserved';

  update equipment_requests
    set status = 'Cancelled', fulfillment_note = null
    where event_id = p_event_id and status <> 'Cancelled';
end;
$$;
